window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[5]=[{"t": "h", "l": 0, "s": "Лекц 5. Хэмжүүрийн шинэ технологи ба процессын түвшин", "h": "<b>Лекц 5. Хэмжүүрийн шинэ технологи ба процессын түвшин</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Уламжлалт гүйдлийн (ГТ) ба хүчдэлийн трансформаторын (ХТ) ажиллах зарчим, нарийвчлалын анги, хязгаарлалтыг ойлгох; тогтмол бүрэлдэхүүнтэй богино холболтын үеийн ГТ-ийн ханалт, ХТ-ийн феррорезонансыг тооцоолох; оптик ГТ, Роговскийн ороомог, хүчдэл хуваагч зэрэг бага чадлын хэмжүүрийн трансформаторын (LPIT) физик зарчим, IEC 61869 цувралын шаардлагыг судлах; нэгтгэх төхөөрөмж (MU), дижитал гаралт, процессын шинын нарийвчлал, хоцрогдол, зурвасын өргөнийг тооцоолж, дижитал дэд станцад хэрэглэх нөхцөлийг үнэлэх.", "h": "<b>Лекцийн зорилго.</b> Уламжлалт гүйдлийн (ГТ) ба хүчдэлийн трансформаторын (ХТ) ажиллах зарчим, нарийвчлалын анги, хязгаарлалтыг ойлгох; тогтмол бүрэлдэхүүнтэй богино холболтын үеийн ГТ-ийн ханалт, ХТ-ийн феррорезонансыг тооцоолох; оптик ГТ, Роговскийн ороомог, хүчдэл хуваагч зэрэг бага чадлын хэмжүүрийн трансформаторын (LPIT) физик зарчим, IEC 61869 цувралын шаардлагыг судлах; нэгтгэх төхөөрөмж (MU), дижитал гаралт, процессын шинын нарийвчлал, хоцрогдол, зурвасын өргөнийг тооцоолж, дижитал дэд станцад хэрэглэх нөхцөлийг үнэлэх.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: гүйдлийн трансформатор, хүчдэлийн трансформатор, нарийвчлалын анги, хугарлын цэг, ханалт, X/R харьцаа, феррорезонанс, багтаамжийн ХТ, Фарадейн эффект, Роговскийн ороомог, LPIT, IEC 61869, нэгтгэх төхөөрөмж, түүвэрлэлтийн утга (SV), процессын шина.", "h": "<b>Түлхүүр үг:</b> гүйдлийн трансформатор, хүчдэлийн трансформатор, нарийвчлалын анги, хугарлын цэг, ханалт, X/R харьцаа, феррорезонанс, багтаамжийн ХТ, Фарадейн эффект, Роговскийн ороомог, LPIT, IEC 61869, нэгтгэх төхөөрөмж, түүвэрлэлтийн утга (SV), процессын шина.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. Хэмжүүрийн\nтрансформаторын үүрэг ба хөгжил", "h": "1. Хэмжүүрийн\nтрансформаторын үүрэг ба хөгжил"}, {"t": "h", "l": 2, "s": "1.1. Үүрэг ба шаардлага", "h": "1.1. Үүрэг ба шаардлага"}, {"t": "p", "s": "Хэмжүүрийн трансформатор нь өндөр хүчдэлийн хэлхээний гүйдэл, хүчдэлийг хамгаалалт, хэмжилт, тоолуур, удирдлагын төхөөрөмжид тохирох стандарт түвшинд (1 А эсвэл 5 А, 100/√(3) В) бууруулж, тэдгээрийг өндөр хүчдэлээс галваник байдлаар тусгаарлах үүрэгтэй. Дэд станцын бүх «нүд» — хамгаалалт, тоолуур, SCADA, синхрофазор хэмжилт — хэмжүүрийн трансформатороор дамжин анхдагч хэлхээг «хардаг» тул тэдгээрийн нарийвчлал, найдвартай ажиллагаа нь бүх хоёрдогч системийн чанарыг тодорхойлно.", "h": "Хэмжүүрийн трансформатор нь өндөр хүчдэлийн хэлхээний гүйдэл, хүчдэлийг хамгаалалт, хэмжилт, тоолуур, удирдлагын төхөөрөмжид тохирох стандарт түвшинд (1 А эсвэл 5 А, 100/√(3) В) бууруулж, тэдгээрийг өндөр хүчдэлээс галваник байдлаар тусгаарлах үүрэгтэй. Дэд станцын бүх «нүд» — хамгаалалт, тоолуур, SCADA, синхрофазор хэмжилт — хэмжүүрийн трансформатороор дамжин анхдагч хэлхээг «хардаг» тул тэдгээрийн нарийвчлал, найдвартай ажиллагаа нь бүх хоёрдогч системийн чанарыг тодорхойлно."}, {"t": "p", "s": "Хэмжүүрийн трансформаторт тавигдах үндсэн шаардлагууд нь:", "h": "Хэмжүүрийн трансформаторт тавигдах үндсэн шаардлагууд нь:"}, {"t": "p", "s": "Нарийвчлал — хэвийн горимд (тоолуур, хэмжилт) 0.1–0.5 %, богино холболтын үед (хамгаалалт) 5–10 %-ийн алдаатай байх;", "h": "• <b>Нарийвчлал</b> — хэвийн горимд (тоолуур, хэмжилт) 0.1–0.5 %, богино холболтын үед (хамгаалалт) 5–10 %-ийн алдаатай байх;"}, {"t": "p", "s": "Динамик хүрээ — ачааллын бага гүйдлээс (нэрлэсний 1 %) богино холболтын гүйдэл хүртэл (нэрлэсний 20–50 дахин) хувиргах;", "h": "• <b>Динамик хүрээ</b> — ачааллын бага гүйдлээс (нэрлэсний 1 %) богино холболтын гүйдэл хүртэл (нэрлэсний 20–50 дахин) хувиргах;"}, {"t": "p", "s": "Давтамжийн зурвас — гармоник, шилжилтийн процесс, тогтмол бүрэлдэхүүнийг дамжуулах;", "h": "• <b>Давтамжийн зурвас</b> — гармоник, шилжилтийн процесс, тогтмол бүрэлдэхүүнийг дамжуулах;"}, {"t": "p", "s": "Тусгаарлага, механик бат бэх — системийн хүчдэл, хэт хүчдэл, богино холболтын динамик, дулааны хүчийг тэсвэрлэх;", "h": "• <b>Тусгаарлага, механик бат бэх</b> — системийн хүчдэл, хэт хүчдэл, богино холболтын динамик, дулааны хүчийг тэсвэрлэх;"}, {"t": "p", "s": "Аюулгүй байдал — ГТ-ийн хоёрдогч хэлхээ задрахад үүсэх аюултай хүчдэл, тосон тоноглолын дэлбэрэлт, галын аюулгүй байх.", "h": "• <b>Аюулгүй байдал</b> — ГТ-ийн хоёрдогч хэлхээ задрахад үүсэх аюултай хүчдэл, тосон тоноглолын дэлбэрэлт, галын аюулгүй байх."}, {"t": "h", "l": 2, "s": "1.2. IEC 61869 цуврал стандарт", "h": "1.2. IEC 61869 цуврал стандарт"}, {"t": "p", "s": "Өмнө нь ГТ-ийг IEC 60044-1, ХТ-ийг IEC 60044-2, электрон хэмжүүрийн трансформаторыг IEC 60044-7, -8 стандартаар зохицуулдаг байсан. 2007 оноос эхлэн эдгээрийг нэгдсэн IEC 61869 цувралаар орлуулсан бөгөөд ерөнхий шаардлагыг 1-р хэсэгт, тодорхой төрлийн нэмэлт шаардлагыг бусад хэсэгт өгдөг (Хүснэгт 5.1). Цувралын онцлог нь уламжлалт ба бага чадлын (LPIT) хэмжүүрийн трансформатор, тэдгээрийн дижитал интерфейсийг нэг логик бүтцэд оруулсан явдал юм.", "h": "Өмнө нь ГТ-ийг IEC 60044-1, ХТ-ийг IEC 60044-2, электрон хэмжүүрийн трансформаторыг IEC 60044-7, -8 стандартаар зохицуулдаг байсан. 2007 оноос эхлэн эдгээрийг нэгдсэн IEC 61869 цувралаар орлуулсан бөгөөд ерөнхий шаардлагыг 1-р хэсэгт, тодорхой төрлийн нэмэлт шаардлагыг бусад хэсэгт өгдөг (Хүснэгт 5.1). Цувралын онцлог нь уламжлалт ба бага чадлын (LPIT) хэмжүүрийн трансформатор, тэдгээрийн дижитал интерфейсийг нэг логик бүтцэд оруулсан явдал юм."}, {"t": "cap", "s": "Хүснэгт 5.1. IEC 61869 цувралын гол хэсгүүд", "h": "Хүснэгт 5.1. IEC 61869 цувралын гол хэсгүүд"}, {"t": "tbl", "s": "", "head": ["Хэсэг", "Агуулга"], "rows": [["IEC 61869-1", "Ерөнхий шаардлага (бүх хэмжүүрийн трансформатор)"], ["IEC 61869-2", "Гүйдлийн трансформаторын нэмэлт шаардлага (хэмжүүрийн ба хамгаалалтын анги, TPX/TPY/TPZ)"], ["IEC 61869-3", "Индуктив хүчдэлийн трансформатор"], ["IEC 61869-4", "Хосолсон (гүйдэл+хүчдэл) трансформатор"], ["IEC 61869-5", "Багтаамжийн хүчдэлийн трансформатор (CVT)"], ["IEC 61869-6", "Бага чадлын хэмжүүрийн трансформаторын (LPIT) ерөнхий шаардлага"], ["IEC 61869-9", "Хэмжүүрийн трансформаторын дижитал интерфейс (нэгтгэх төхөөрөмж)"], ["IEC 61869-10, -11", "Идэвхгүй бага чадлын ГТ (LPCT) ба ХТ (LPVT)"], ["IEC 61869-13", "Бие даасан нэгтгэх төхөөрөмж (SAMU)"]]}, {"t": "p", "s": "Хэмжүүрийн трансформаторыг зарчмаар нь хоёр бүлэгт хуваана: (1) уламжлалт — ферросоронзон цөмтэй, хоёрдогчдоо стандарт 1/5 А, 100 В-ын чадалтай гаралттай; (2) уламжлалт бус буюу бага чадлын (Non-Conventional Instrument Transformer, NCIT; Low-Power Instrument Transformer, LPIT) — оптик, Роговскийн ороомог, хүчдэл хуваагч, бага чадлын төмөр цөмт ГТ (LPCT) зэрэг мэдрэгчтэй, гаралт нь милливольтын аналог дохио эсвэл дижитал урсгал. Дижитал дэд станцад хоёр төрөл хоёулаа нэгтгэх төхөөрөмжөөр (Merging Unit, MU) дамжин процессын шинад холбогдоно.", "h": "Хэмжүүрийн трансформаторыг зарчмаар нь хоёр бүлэгт хуваана: (1) <b>уламжлалт</b> — ферросоронзон цөмтэй, хоёрдогчдоо стандарт 1/5 А, 100 В-ын чадалтай гаралттай; (2) <b>уламжлалт бус</b> буюу <b>бага чадлын</b> (Non-Conventional Instrument Transformer, NCIT; Low-Power Instrument Transformer, LPIT) — оптик, Роговскийн ороомог, хүчдэл хуваагч, бага чадлын төмөр цөмт ГТ (LPCT) зэрэг мэдрэгчтэй, гаралт нь милливольтын аналог дохио эсвэл дижитал урсгал. Дижитал дэд станцад хоёр төрөл хоёулаа нэгтгэх төхөөрөмжөөр (Merging Unit, MU) дамжин процессын шинад холбогдоно."}, {"t": "h", "l": 1, "s": "2. Уламжлалт гүйдлийн\nтрансформатор", "h": "2. Уламжлалт гүйдлийн\nтрансформатор"}, {"t": "h", "l": 2, "s": "2.1. Ажиллах зарчим ба бүтэц", "h": "2.1. Ажиллах зарчим ба бүтэц"}, {"t": "p", "s": "ГТ-ийн анхдагч ороомог (ихэвчлэн нэг эргэлт — шугамын дамжуулагч өөрөө) цуваа холбогдож, хоёрдогч ороомог нь бага эсэргүүцэлтэй ачаалал (реле, тоолуур, холболтын утас)-аар бараг богино холбогдсон горимд ажилладаг. Хамгийн тохиромжтой ГТ-д анхдагч ба хоёрдогчийн магнит хөдөлгөгч хүч тэнцэх (I 1w 1=I 2w 2) боловч бодит ГТ-д цөмийг соронзлоход гүйдлийн тодорхой хэсэг (I e) зарцуулагддаг. Хоёрдогч тал руу шилжүүлсэн орлуулах схемийг Зураг 5.2, а-д үзүүлэв: анхдагч гүйдлийн эх үүсвэр I 1/K n-аас соронзлох шугаман бус салаа L μ ба хоёрдогч хэлхээ (R ct+R b) тэжээгдэнэ.", "h": "ГТ-ийн анхдагч ороомог (ихэвчлэн нэг эргэлт — шугамын дамжуулагч өөрөө) цуваа холбогдож, хоёрдогч ороомог нь бага эсэргүүцэлтэй ачаалал (реле, тоолуур, холболтын утас)-аар бараг богино холбогдсон горимд ажилладаг. Хамгийн тохиромжтой ГТ-д анхдагч ба хоёрдогчийн магнит хөдөлгөгч хүч тэнцэх (I<sub>1</sub>w<sub>1</sub>=I<sub>2</sub>w<sub>2</sub>) боловч бодит ГТ-д цөмийг соронзлоход гүйдлийн тодорхой хэсэг (I<sub>e</sub>) зарцуулагддаг. Хоёрдогч тал руу шилжүүлсэн орлуулах схемийг Зураг 5.2, а-д үзүүлэв: анхдагч гүйдлийн эх үүсвэр I<sub>1</sub>/K<sub>n</sub>-аас соронзлох шугаман бус салаа L<sub>μ</sub> ба хоёрдогч хэлхээ (R<sub>ct</sub>+R<sub>b</sub>) тэжээгдэнэ."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.1. 110–220 кВ-ын «амьд савт» (live-tank) тосон ГТ-ийн огтлол: дамжуулагчийг тойрсон цагираган цөмүүд толгойн саванд байрлана", "h": "Зураг 5.1. 110–220 кВ-ын «амьд савт» (live-tank) тосон ГТ-ийн огтлол: дамжуулагчийг тойрсон цагираган цөмүүд толгойн саванд байрлана"}, {"t": "p", "s": "Өндөр хүчдэлийн ГТ нь бүтцээрээ «амьд савт» (live-tank, цөм нь толгойн хэсэгт өндөр потенциалд), «газардсан савт» (dead-tank, цөм нь доод саванд газрын потенциалд), шинын оролтын (bushing-type) ба КРУЭ/GIS-д суурилагдсан цагираган ГТ гэж ангилагдана. Зураг 5.1-д амьд савт ГТ-ийн толгойг үзүүлэв: нэг анхдагч дамжуулагчийг 3–6 бие даасан цагираган цөм тойрсон бөгөөд цөм бүр хэмжүүрийн, шугамын хамгаалалтын, шинын хамгаалалтын гэх мэт тусдаа зориулалттай. Цөмүүдийг цаас-тосон эсвэл SF6 тусгаарлага, потенциал тэгшитгэх дэлгэцээр (экран) өндөр потенциалаас тусгаарлаж, хоёрдогч гаргалгааг тусгаарлагч баганын доторх хоолойгоор доод хайрцагт гаргана.", "h": "Өндөр хүчдэлийн ГТ нь бүтцээрээ «амьд савт» (live-tank, цөм нь толгойн хэсэгт өндөр потенциалд), «газардсан савт» (dead-tank, цөм нь доод саванд газрын потенциалд), шинын оролтын (bushing-type) ба КРУЭ/GIS-д суурилагдсан цагираган ГТ гэж ангилагдана. Зураг 5.1-д амьд савт ГТ-ийн толгойг үзүүлэв: нэг анхдагч дамжуулагчийг 3–6 бие даасан цагираган цөм тойрсон бөгөөд цөм бүр хэмжүүрийн, шугамын хамгаалалтын, шинын хамгаалалтын гэх мэт тусдаа зориулалттай. Цөмүүдийг цаас-тосон эсвэл SF6 тусгаарлага, потенциал тэгшитгэх дэлгэцээр (экран) өндөр потенциалаас тусгаарлаж, хоёрдогч гаргалгааг тусгаарлагч баганын доторх хоолойгоор доод хайрцагт гаргана."}, {"t": "p", "s": "ГТ-ийн гүйдлийн (харьцааны) алдаа ба фазын шилжилтийг дараах байдлаар тодорхойлно:", "h": "ГТ-ийн гүйдлийн (харьцааны) алдаа ба фазын шилжилтийг дараах байдлаар тодорхойлно:"}, {"t": "eq", "s": "ε i=(K nI 2−I 1)/I 1⋅100 %, K n=(I 1н)/(I 2н) (5.1)", "h": "ε<sub>i</sub>=(K<sub>n</sub>I<sub>2</sub>−I<sub>1</sub>)/I<sub>1</sub>⋅100 %, K<sub>n</sub>=(I<sub>1н</sub>)/(I<sub>2н</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε</mi><mi>i</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>K</mi><mi>n</mi></msub><msub><mi>I</mi><mn>2</mn></msub><mo>−</mo><msub><mi>I</mi><mn>1</mn></msub></mrow><msub><mi>I</mi><mn>1</mn></msub></mfrac><mo>⋅</mo><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>%</mi><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>K</mi><mi>n</mi></msub><mo>=</mo><mfrac><msub><mi>I</mi><mrow><mn>1</mn><mi>н</mi></mrow></msub><msub><mi>I</mi><mrow><mn>2</mn><mi>н</mi></mrow></msub></mfrac></mrow></semantics></math>", "n": "5.1"}, {"t": "p", "s": "энд K n — нэрлэсэн хувиргалтын коэффициент; I 1, I 2 — анхдагч ба хоёрдогч гүйдлийн үйлчлэх утга. Фазын шилжилт Δφ нь хоёрдогч гүйдлийн векторын анхдагч гүйдлийн вектороос тэргүүлэх өнцөг (минутаар) юм. Хамгаалалтын ГТ-ийн хувьд гүйдлийн хэлбэр гажсан үед хуримтлагдсан (composite) алдааг хэрэглэнэ:", "h": "энд K<sub>n</sub> — нэрлэсэн хувиргалтын коэффициент; I<sub>1</sub>, I<sub>2</sub> — анхдагч ба хоёрдогч гүйдлийн үйлчлэх утга. Фазын шилжилт Δφ нь хоёрдогч гүйдлийн векторын анхдагч гүйдлийн вектороос тэргүүлэх өнцөг (минутаар) юм. Хамгаалалтын ГТ-ийн хувьд гүйдлийн хэлбэр гажсан үед хуримтлагдсан (composite) алдааг хэрэглэнэ:"}, {"t": "eq", "s": "ε c=(100)/I 1√(1/T∫ 0^T(K ni 2−i 1)^2dt) % (5.2)", "h": "ε<sub>c</sub>=(100)/I<sub>1</sub>√(1/T∫<sub>0</sub><sup>T</sup>(K<sub>n</sub>i<sub>2</sub>−i<sub>1</sub>)<sup>2</sup>dt) %", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε</mi><mi>c</mi></msub><mo>=</mo><mfrac><mn>100</mn><msub><mi>I</mi><mn>1</mn></msub></mfrac><msqrt><mrow><mfrac><mn>1</mn><mi>T</mi></mfrac><msubsup><mo>∫</mo><mn>0</mn><mi>T</mi></msubsup><msup><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>K</mi><mi>n</mi></msub><msub><mi>i</mi><mn>2</mn></msub><mo>−</mo><msub><mi>i</mi><mn>1</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mn>2</mn></msup><mi>d</mi><mi>t</mi></mrow></msqrt><mspace width=\"0.278em\"></mspace><mi>%</mi></mrow></semantics></math>", "n": "5.2"}, {"t": "p", "s": "энд i 1, i 2 — агшин зуурын гүйдэл, T — нэг үе. Хуримтлагдсан алдаа нь харьцааны алдаа, фазын шилжилт, гармоникийн нөлөөг нэгтгэн илэрхийлнэ.", "h": "энд i<sub>1</sub>, i<sub>2</sub> — агшин зуурын гүйдэл, T — нэг үе. Хуримтлагдсан алдаа нь харьцааны алдаа, фазын шилжилт, гармоникийн нөлөөг нэгтгэн илэрхийлнэ."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.2. ГТ-ийн орлуулах схем ба соронзлолын муруй (хугарлын цэгийг IEC 61869-2-оор: хүчдэл 10 % өсөхөд соронзлох гүйдэл 50 % өсөх цэг)", "h": "Зураг 5.2. ГТ-ийн орлуулах схем ба соронзлолын муруй (хугарлын цэгийг IEC 61869-2-оор: хүчдэл 10 % өсөхөд соронзлох гүйдэл 50 % өсөх цэг)"}, {"t": "p", "s": "Соронзлолын муруй (Зураг 5.2, б) нь ГТ-ийн хамгаалалтын чадварыг тодорхойлох гол шинж чанар юм. Шугаман хэсэгт соронзлох гүйдэл маш бага (миллиампер), харин хугарлын цэгээс (knee point, E k) хойш цөм ханаж, соронзлох гүйдэл огцом өсөн хоёрдогч гүйдлийг «булааж» эхэлнэ. IEC 61869-2-оор хугарлын цэг нь хоёрдогч ЦХХ-ийг 10 %-иар өсгөхөд соронзлох гүйдэл 50 %-иар өсөх цэг юм.", "h": "Соронзлолын муруй (Зураг 5.2, б) нь ГТ-ийн хамгаалалтын чадварыг тодорхойлох гол шинж чанар юм. Шугаман хэсэгт соронзлох гүйдэл маш бага (миллиампер), харин <b>хугарлын цэгээс</b> (knee point, E<sub>k</sub>) хойш цөм ханаж, соронзлох гүйдэл огцом өсөн хоёрдогч гүйдлийг «булааж» эхэлнэ. IEC 61869-2-оор хугарлын цэг нь хоёрдогч ЦХХ-ийг 10 %-иар өсгөхөд соронзлох гүйдэл 50 %-иар өсөх цэг юм."}, {"t": "h", "l": 2, "s": "2.2. Нарийвчлалын анги", "h": "2.2. Нарийвчлалын анги"}, {"t": "p", "s": "Хэмжүүрийн ГТ нь ачааллын хүрээнд (нэрлэсний 1–120 %) өндөр нарийвчлалтай байх ёстой бол богино холболтын үед эсрэгээр ханах нь хэмжүүрийн хэрэгслийг хэт гүйдлээс хамгаалдаг. Үүнийг аюулгүйн коэффициент FS (Instrument Security Factor)-ээр илэрхийлнэ: FS=5 бол анхдагч гүйдэл нэрлэсний 5 дахин хүрэхэд хуримтлагдсан алдаа 10 %-иас их байна. Хэмжүүрийн ангиудын алдааны хязгаарыг Хүснэгт 5.2-т үзүүлэв. «S» үсэгтэй (0.2S, 0.5S) ангиуд нь нэрлэсний 1 % хүртэл бага гүйдэлд нарийвчлалаа хадгалдаг тул ачаалал их хэлбэлздэг арилжааны тоолуурт хэрэглэнэ.", "h": "Хэмжүүрийн ГТ нь ачааллын хүрээнд (нэрлэсний 1–120 %) өндөр нарийвчлалтай байх ёстой бол богино холболтын үед эсрэгээр <b>ханах</b> нь хэмжүүрийн хэрэгслийг хэт гүйдлээс хамгаалдаг. Үүнийг аюулгүйн коэффициент FS (Instrument Security Factor)-ээр илэрхийлнэ: FS=5 бол анхдагч гүйдэл нэрлэсний 5 дахин хүрэхэд хуримтлагдсан алдаа 10 %-иас их байна. Хэмжүүрийн ангиудын алдааны хязгаарыг Хүснэгт 5.2-т үзүүлэв. «S» үсэгтэй (0.2S, 0.5S) ангиуд нь нэрлэсний 1 % хүртэл бага гүйдэлд нарийвчлалаа хадгалдаг тул ачаалал их хэлбэлздэг арилжааны тоолуурт хэрэглэнэ."}, {"t": "cap", "s": "Хүснэгт 5.2. Хэмжүүрийн ГТ-ийн нарийвчлалын анги (IEC 61869-2), алдааны хязгаар ±", "h": "Хүснэгт 5.2. Хэмжүүрийн ГТ-ийн нарийвчлалын анги (IEC 61869-2), алдааны хязгаар ±"}, {"t": "tbl", "s": "", "head": ["Анги", "1 %", "5 %", "20 %", "100 %", "120 %", "Фазын шилжилт 100 %-д, мин"], "rows": [["0.1", "—", "0.4", "0.2", "0.1", "0.1", "5"], ["0.2S", "0.75", "0.35", "0.2", "0.2", "0.2", "10"], ["0.2", "—", "0.75", "0.35", "0.2", "0.2", "10"], ["0.5S", "1.5", "0.75", "0.5", "0.5", "0.5", "30"], ["0.5", "—", "1.5", "0.75", "0.5", "0.5", "30"], ["1", "—", "3.0", "1.5", "1.0", "1.0", "60"]]}, {"t": "p", "s": "Хамгаалалтын ГТ-ийн ангиуд нь богино холболтын гүйдлийн хүрээнд алдааг хязгаарлана (Хүснэгт 5.3). Жишээлбэл 5P20 гэдэг нь нэрлэсэн ачаалалтай үед анхдагч гүйдэл нэрлэсний 20 дахин (ALF=20, accuracy limit factor) хүртэл хуримтлагдсан алдаа 5 %-иас хэтрэхгүй гэсэн үг. PR ангиуд үлдэгдэл соронзлолыг 10 % хүртэл хязгаарласан (жижиг агаарын завсартай), PX ангийг харин хугарлын цэгийн хүчдэл E k, түүнд харгалзах соронзлох гүйдэл, R ct-ээр тодорхойлдог тул дифференциал хамгаалалтын тооцоонд тохиромжтой. TP (transient performance) ангиуд нь тогтмол бүрэлдэхүүнтэй шилжилтийн процессын үеийн ажиллагааг баталгаажуулна.", "h": "Хамгаалалтын ГТ-ийн ангиуд нь богино холболтын гүйдлийн хүрээнд алдааг хязгаарлана (Хүснэгт 5.3). Жишээлбэл <b>5P20</b> гэдэг нь нэрлэсэн ачаалалтай үед анхдагч гүйдэл нэрлэсний 20 дахин (ALF=20, accuracy limit factor) хүртэл хуримтлагдсан алдаа 5 %-иас хэтрэхгүй гэсэн үг. PR ангиуд үлдэгдэл соронзлолыг 10 % хүртэл хязгаарласан (жижиг агаарын завсартай), PX ангийг харин хугарлын цэгийн хүчдэл E<sub>k</sub>, түүнд харгалзах соронзлох гүйдэл, R<sub>ct</sub>-ээр тодорхойлдог тул дифференциал хамгаалалтын тооцоонд тохиромжтой. TP (transient performance) ангиуд нь тогтмол бүрэлдэхүүнтэй шилжилтийн процессын үеийн ажиллагааг баталгаажуулна."}, {"t": "cap", "s": "Хүснэгт 5.3. Хамгаалалтын ГТ-ийн ангиуд (IEC 61869-2)", "h": "Хүснэгт 5.3. Хамгаалалтын ГТ-ийн ангиуд (IEC 61869-2)"}, {"t": "tbl", "s": "", "head": ["Анги", "Харьцааны алдаа I<sub>1н</sub>-д", "Хязгаарын нөхцөлд алдаа", "Үлдэгдэл соронзлол", "Хэрэглээ"], "rows": [["5P, 5PR", "±1 %, ±60′", "ε<sub>c</sub>≤5 %", "P: тодорхойгүй, PR: ≤10 %", "Шугамын максимал, зайн хамгаалалт"], ["10P, 10PR", "±3 %", "ε<sub>c</sub>≤10 %", "P: тодорхойгүй, PR: ≤10 %", "Максимал гүйдлийн хамгаалалт"], ["PX, PXR", "Эргэлтийн харьцаа ±0.25 %", "E<sub>k</sub>, I<sub>e</sub>, R<sub>ct</sub>-ээр", "PXR: ≤10 %", "Дифференциал, шинын хамгаалалт"], ["TPX", "±0.5 %, ±30′", "ε<sub>̂</sub>≤10 % (агшин зуурын)", "Хязгааргүй (завсаргүй цөм)", "Шилжилтийн горим, нэг циклтэй"], ["TPY", "±1 %, ±60′", "ε<sub>̂</sub>≤10 %", "≤10 % (агаарын завсартай)", "Автомат дахин залгалттай шугам"], ["TPZ", "±1 %, 180±18′", "ε<sub>̂</sub><sub>ac</sub>≤10 %", "Бараг тэг (том завсар)", "Зөвхөн хувьсах бүрэлдэхүүн чухал үед"]]}, {"t": "h", "l": 2, "s": "2.3. Ачаалал ба хязгаарын хүчин\nзүйл", "h": "2.3. Ачаалал ба хязгаарын хүчин\nзүйл"}, {"t": "p", "s": "ГТ-ийн хоёрдогч ЦХХ нь хоёрдогч гүйдэл ба хэлхээний нийт эсэргүүцлийн үржвэр тул бодит ачаалал нэрлэсэн ачааллаас бага байвал ГТ илүү их гүйдлийг ханалтгүй хувиргана. Хязгаарын нөхцөлд шаардагдах ЦХХ ба бодит хязгаарын хүчин зүйл нь:", "h": "ГТ-ийн хоёрдогч ЦХХ нь хоёрдогч гүйдэл ба хэлхээний нийт эсэргүүцлийн үржвэр тул <b>бодит</b> ачаалал нэрлэсэн ачааллаас бага байвал ГТ илүү их гүйдлийг ханалтгүй хувиргана. Хязгаарын нөхцөлд шаардагдах ЦХХ ба бодит хязгаарын хүчин зүйл нь:"}, {"t": "eq", "s": "E al=ALF⋅I 2н (R ct+R bн) (5.3)", "h": "E<sub>al</sub>=ALF⋅I<sub>2н</sub> (R<sub>ct</sub>+R<sub>bн</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E</mi><mrow><mi>a</mi><mi>l</mi></mrow></msub><mo>=</mo><mi>A</mi><mi>L</mi><mi>F</mi><mo>⋅</mo><msub><mi>I</mi><mrow><mn>2</mn><mi>н</mi></mrow></msub><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>R</mi><mrow><mi>c</mi><mi>t</mi></mrow></msub><mo>+</mo><msub><mi>R</mi><mrow><mi>b</mi><mi>н</mi></mrow></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "5.3"}, {"t": "eq", "s": "ALF′=ALF (R ct+R bн)/(R ct+R b) (5.4)", "h": "ALF′=ALF (R<sub>ct</sub>+R<sub>bн</sub>)/(R<sub>ct</sub>+R<sub>b</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mi>L</mi><mi>F</mi><mi>′</mi><mo>=</mo><mi>A</mi><mi>L</mi><mi>F</mi><mspace width=\"0.167em\"></mspace><mfrac><mrow><msub><mi>R</mi><mrow><mi>c</mi><mi>t</mi></mrow></msub><mo>+</mo><msub><mi>R</mi><mrow><mi>b</mi><mi>н</mi></mrow></msub></mrow><mrow><msub><mi>R</mi><mrow><mi>c</mi><mi>t</mi></mrow></msub><mo>+</mo><msub><mi>R</mi><mi>b</mi></msub></mrow></mfrac></mrow></semantics></math>", "n": "5.4"}, {"t": "p", "s": "энд R bн=S н/I 2н^2 — нэрлэсэн ачааллын эсэргүүцэл; R b — бодит ачаалал (реле + холболтын утас). Холболтын утасны эсэргүүцлийг нэг фазын газардлагын гэмтэлд (утасны хоёр талын урт) дараах байдлаар олно:", "h": "энд R<sub>bн</sub>=S<sub>н</sub>/I<sub>2н</sub><sup>2</sup> — нэрлэсэн ачааллын эсэргүүцэл; R<sub>b</sub> — бодит ачаалал (реле + холболтын утас). Холболтын утасны эсэргүүцлийг нэг фазын газардлагын гэмтэлд (утасны хоёр талын урт) дараах байдлаар олно:"}, {"t": "eq", "s": "R л=ρ 2l/A (5.5)", "h": "R<sub>л</sub>=ρ 2l/A", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>л</mi></msub><mo>=</mo><mi>ρ</mi><mspace width=\"0.167em\"></mspace><mfrac><mrow><mn>2</mn><mi>l</mi></mrow><mi>A</mi></mfrac></mrow></semantics></math>", "n": "5.5"}, {"t": "p", "s": "энд ρ — зэсийн хувийн эсэргүүцэл (20 °C-д 0.0175 Ом·мм²/м), l — ГТ-ээс релений шүүгээ хүртэлх зай, м; A — судлын огтлол, мм². Монголын нөхцөлд ил талбайн кабелийн температур зун +60 °C хүрч, эсэргүүцэл 16 % орчим өсдөгийг тооцох хэрэгтэй.", "h": "энд ρ — зэсийн хувийн эсэргүүцэл (20 °C-д 0.0175 Ом·мм²/м), l — ГТ-ээс релений шүүгээ хүртэлх зай, м; A — судлын огтлол, мм². Монголын нөхцөлд ил талбайн кабелийн температур зун +60 °C хүрч, эсэргүүцэл 16 % орчим өсдөгийг тооцох хэрэгтэй."}, {"t": "p", "s": "Жишээ 5.1. 110 кВ-ын шугамын 600/1 А, 5P20, 15 ВА ГТ-ийн хоёрдогч ороомгийн эсэргүүцэл R ct=4 Ом. Микропроцессорт реленийн хэрэглээ 0.1 ВА, ГТ-ээс реле хүртэл 50 м, 2.5 мм² зэс кабель. Бодит хязгаарын хүчин зүйлийг тодорхойлъё.", "h": "<b>Жишээ 5.1.</b> 110 кВ-ын шугамын 600/1 А, 5P20, 15 ВА ГТ-ийн хоёрдогч ороомгийн эсэргүүцэл R<sub>ct</sub>=4 Ом. Микропроцессорт реленийн хэрэглээ 0.1 ВА, ГТ-ээс реле хүртэл 50 м, 2.5 мм² зэс кабель. Бодит хязгаарын хүчин зүйлийг тодорхойлъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. Нэрлэсэн ачаалал R bн=15/1^2=15 Ом. (5.5)-аар R л=0.0175⋅2⋅50/2.5=0.70 Ом; реле 0.1/1^2=0.1 Ом; R b=0.80 Ом. (5.3)-аар E al=20⋅1⋅(4+15)=380 В. (5.4)-өөр ALF′=20⋅(4+15)/(4+0.8)=79.2. Иймээс бодит ачааллаар ГТ нь нэрлэсний 79 дахин (47.5 кА) гүйдлийг 5 %-ийн алдаатай хувиргана. Микропроцессорт реле бага ачаалалтай тул орчин үеийн ГТ-ийн бодит хязгаарын хүчин зүйл нэрлэснээс хэд дахин их байдаг ч энэ нь зөвхөн тэгш хэмт гүйдэлд хамаарна (§2.4).", "h": "<i>Бодолт.</i> Нэрлэсэн ачаалал R<sub>bн</sub>=15/1<sup>2</sup>=15 Ом. (5.5)-аар R<sub>л</sub>=0.0175⋅2⋅50/2.5=0.70 Ом; реле 0.1/1<sup>2</sup>=0.1 Ом; R<sub>b</sub>=0.80 Ом. (5.3)-аар E<sub>al</sub>=20⋅1⋅(4+15)=380 В. (5.4)-өөр ALF′=20⋅(4+15)/(4+0.8)=79.2. Иймээс бодит ачааллаар ГТ нь нэрлэсний 79 дахин (47.5 кА) гүйдлийг 5 %-ийн алдаатай хувиргана. Микропроцессорт реле бага ачаалалтай тул орчин үеийн ГТ-ийн бодит хязгаарын хүчин зүйл нэрлэснээс хэд дахин их байдаг ч энэ нь зөвхөн <b>тэгш хэмт</b> гүйдэлд хамаарна (§2.4).", "x": "ex"}, {"t": "h", "l": 2, "s": "2.4. Тогтмол бүрэлдэхүүнтэй\nханалт", "h": "2.4. Тогтмол бүрэлдэхүүнтэй\nханалт"}, {"t": "p", "s": "Богино холболт хүчдэлийн тэг орчим үүсвэл гүйдэлд унтрах тогтмол бүрэлдэхүүн нэмэгдэнэ:", "h": "Богино холболт хүчдэлийн тэг орчим үүсвэл гүйдэлд унтрах тогтмол бүрэлдэхүүн нэмэгдэнэ:"}, {"t": "eq", "s": "i 1(t)=√(2) I k(e^−t/T 1−cosωt), T 1=X/ωR (5.6)", "h": "i<sub>1</sub>(t)=√(2) I<sub>k</sub>(e<sup>−t/T<sub>1</sub></sup>−cosωt), T<sub>1</sub>=X/ωR", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>i</mi><mn>1</mn></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><msqrt><mn>2</mn></msqrt><mspace width=\"0.167em\"></mspace><msub><mi>I</mi><mi>k</mi></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi>/</mi><msub><mi>T</mi><mn>1</mn></msub></mrow></msup><mo>−</mo><mo>cos</mo><mi>ω</mi><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>T</mi><mn>1</mn></msub><mo>=</mo><mfrac><mi>X</mi><mrow><mi>ω</mi><mi>R</mi></mrow></mfrac></mrow></semantics></math>", "n": "5.6"}, {"t": "p", "s": "энд I k — тэгш хэмт богино холболтын гүйдлийн үйлчлэх утга, T 1 — анхдагч хэлхээний хугацааны тогтмол. Тогтмол бүрэлдэхүүн нь трансформаторын хувьд «хувиргагдахгүй» тул цөмд соронзон урсгалыг хуримтлуулна. Соронзлох гүйдлийг үл тооцож, хоёрдогч хугацааны тогтмол T s→∞ (завсаргүй цөм) гэвэл цөмийн урсгалын тэгш хэмт урсгалын далайцад харьцуулсан харьцаа:", "h": "энд I<sub>k</sub> — тэгш хэмт богино холболтын гүйдлийн үйлчлэх утга, T<sub>1</sub> — анхдагч хэлхээний хугацааны тогтмол. Тогтмол бүрэлдэхүүн нь трансформаторын хувьд «хувиргагдахгүй» тул цөмд соронзон урсгалыг хуримтлуулна. Соронзлох гүйдлийг үл тооцож, хоёрдогч хугацааны тогтмол T<sub>s</sub>→∞ (завсаргүй цөм) гэвэл цөмийн урсгалын тэгш хэмт урсгалын далайцад харьцуулсан харьцаа:"}, {"t": "eq", "s": "(Ψ(t))/(Ψ ac)=ωT 1(1−e^−t/T 1)−sinωt (5.7)", "h": "(Ψ(t))/(Ψ<sub>ac</sub>)=ωT<sub>1</sub>(1−e<sup>−t/T<sub>1</sub></sup>)−sinωt", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>Ψ</mi><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow><msub><mi>Ψ</mi><mrow><mi>a</mi><mi>c</mi></mrow></msub></mfrac><mo>=</mo><mi>ω</mi><msub><mi>T</mi><mn>1</mn></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>1</mn><mo>−</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi>/</mi><msub><mi>T</mi><mn>1</mn></msub></mrow></msup><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>−</mo><mo>sin</mo><mi>ω</mi><mi>t</mi></mrow></semantics></math>", "n": "5.7"}, {"t": "p", "s": "болох бөгөөд хамгийн их утга нь ойролцоогоор 1+ωT 1=1+X/R байна. Иймээс тогтмол бүрэлдэхүүнтэй гүйдлийг ханалтгүй хувиргахад хугарлын цэгийн хүчдэл тэгш хэмт горимынхоос (1+X/R) дахин их байх шаардлагатай. Цөмд өмнөх гэмтлээс үлдсэн соронзлол (үлдэгдлийн коэффициент K r, ханалтын урсгалд харьцуулсан) байвал нөөц урсгал (1−K r) дахин багасна. Эцэст нь хугарлын цэгийн хүчдэлийн шаардлага:", "h": "болох бөгөөд хамгийн их утга нь ойролцоогоор 1+ωT<sub>1</sub>=1+X/R байна. Иймээс тогтмол бүрэлдэхүүнтэй гүйдлийг ханалтгүй хувиргахад хугарлын цэгийн хүчдэл тэгш хэмт горимынхоос (1+X/R) дахин их байх шаардлагатай. Цөмд өмнөх гэмтлээс үлдсэн соронзлол (үлдэгдлийн коэффициент K<sub>r</sub>, ханалтын урсгалд харьцуулсан) байвал нөөц урсгал (1−K<sub>r</sub>) дахин багасна. Эцэст нь хугарлын цэгийн хүчдэлийн шаардлага:"}, {"t": "eq", "s": "E k≥(1+X/R)/(1−K r) I k/K n (R ct+R b) (5.8)", "h": "E<sub>k</sub>≥(1+X/R)/(1−K<sub>r</sub>) I<sub>k</sub>/K<sub>n</sub> (R<sub>ct</sub>+R<sub>b</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E</mi><mi>k</mi></msub><mo>≥</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>X</mi><mi>/</mi><mi>R</mi></mrow><mrow><mn>1</mn><mo>−</mo><msub><mi>K</mi><mi>r</mi></msub></mrow></mfrac><mspace width=\"0.278em\"></mspace><mfrac><msub><mi>I</mi><mi>k</mi></msub><msub><mi>K</mi><mi>n</mi></msub></mfrac><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>R</mi><mrow><mi>c</mi><mi>t</mi></mrow></msub><mo>+</mo><msub><mi>R</mi><mi>b</mi></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "5.8"}, {"t": "p", "s": "IEEE Std C37.110-оор хамгаалалтын ГТ-ийн ханалт эхлэх хугацааг ойролцоогоор дараах томьёогоор үнэлнэ:", "h": "IEEE Std C37.110-оор хамгаалалтын ГТ-ийн ханалт эхлэх хугацааг ойролцоогоор дараах томьёогоор үнэлнэ:"}, {"t": "eq", "s": "K s=E k/((I k/K n)(R ct+R b)) (5.9)", "h": "K<sub>s</sub>=E<sub>k</sub>/((I<sub>k</sub>/K<sub>n</sub>)(R<sub>ct</sub>+R<sub>b</sub>))", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>K</mi><mi>s</mi></msub><mo>=</mo><mfrac><msub><mi>E</mi><mi>k</mi></msub><mrow><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>I</mi><mi>k</mi></msub><mi>/</mi><msub><mi>K</mi><mi>n</mi></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>R</mi><mrow><mi>c</mi><mi>t</mi></mrow></msub><mo>+</mo><msub><mi>R</mi><mi>b</mi></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></mfrac></mrow></semantics></math>", "n": "5.9"}, {"t": "eq", "s": "t s=−T 1ln(1−(K s−1)/(X/R)) (5.10)", "h": "t<sub>s</sub>=−T<sub>1</sub>ln(1−(K<sub>s</sub>−1)/(X/R))", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mi>s</mi></msub><mo>=</mo><mo>−</mo><msub><mi>T</mi><mn>1</mn></msub><mo>ln</mo><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>1</mn><mo>−</mo><mfrac><mrow><msub><mi>K</mi><mi>s</mi></msub><mo>−</mo><mn>1</mn></mrow><mrow><mi>X</mi><mi>/</mi><mi>R</mi></mrow></mfrac><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "5.10"}, {"t": "p", "s": "энд K s — ханалтын нөөцийн коэффициент. Хэрэв K s−1≥X/R бол ГТ ханахгүй. (5.10) нь хувьсах урсгалын хэлбэлзлийг тооцоогүй тул ихэвчлэн нөөцтэй (бага) үр дүн өгнө.", "h": "энд K<sub>s</sub> — ханалтын нөөцийн коэффициент. Хэрэв K<sub>s</sub>−1≥X/R бол ГТ ханахгүй. (5.10) нь хувьсах урсгалын хэлбэлзлийг тооцоогүй тул ихэвчлэн нөөцтэй (бага) үр дүн өгнө."}, {"t": "p", "s": "Жишээ 5.2. 110 кВ-ын дэд станцын шугамд 1200/1 А ГТ суурилуулсан. Хамгийн их богино холболтын гүйдэл I k=20 кА, X/R=15, R ct=6 Ом, R b=2 Ом. Шаардлагатай хугарлын цэгийн хүчдэлийг (а) үлдэгдэл соронзлолгүй, (б) K r=0.8 үед тодорхойлъё.", "h": "<b>Жишээ 5.2.</b> 110 кВ-ын дэд станцын шугамд 1200/1 А ГТ суурилуулсан. Хамгийн их богино холболтын гүйдэл I<sub>k</sub>=20 кА, X/R=15, R<sub>ct</sub>=6 Ом, R<sub>b</sub>=2 Ом. Шаардлагатай хугарлын цэгийн хүчдэлийг (а) үлдэгдэл соронзлолгүй, (б) K<sub>r</sub>=0.8 үед тодорхойлъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. Хоёрдогч гүйдэл I k/K n=20000/1200=16.67 А; тэгш хэмт горимын ЦХХ 16.67⋅(6+2)=133.3 В. T 1=15/(2π⋅50)=47.7 мс. (а) (5.8)-аар E k≥(1+15)⋅133.3=2133 В. (б) E k≥16⋅133.3/(1−0.8)=10 667 В. (б) хувилбарыг практикт хэрэгжүүлэх боломжгүй (цөм хэт том), тиймээс үлдэгдэл соронзлолыг хязгаарласан TPY эсвэл PXR анги сонгох, эсвэл ханалтад тэсвэртэй хамгаалалтын алгоритм (ханалт илрүүлэгч, ханалтаас өмнө шийдвэр гаргах) хэрэглэх шаардлагатай. Шугамын зайн хамгаалалт ихэвчлэн эхний 1–1.5 үед шийдвэр гаргадаг тул бүрэн (1+X/R) нөөцийг шаардахгүй, харин шинын дифференциал хамгаалалт гаднах гэмтэлд тогтвортой байхын тулд бүрэн нөөц шаардах нь бий.", "h": "<i>Бодолт.</i> Хоёрдогч гүйдэл I<sub>k</sub>/K<sub>n</sub>=20000/1200=16.67 А; тэгш хэмт горимын ЦХХ 16.67⋅(6+2)=133.3 В. T<sub>1</sub>=15/(2π⋅50)=47.7 мс. (а) (5.8)-аар E<sub>k</sub>≥(1+15)⋅133.3=2133 В. (б) E<sub>k</sub>≥16⋅133.3/(1−0.8)=10 667 В. (б) хувилбарыг практикт хэрэгжүүлэх боломжгүй (цөм хэт том), тиймээс үлдэгдэл соронзлолыг хязгаарласан TPY эсвэл PXR анги сонгох, эсвэл ханалтад тэсвэртэй хамгаалалтын алгоритм (ханалт илрүүлэгч, ханалтаас өмнө шийдвэр гаргах) хэрэглэх шаардлагатай. Шугамын зайн хамгаалалт ихэвчлэн эхний 1–1.5 үед шийдвэр гаргадаг тул бүрэн (1+X/R) нөөцийг шаардахгүй, харин шинын дифференциал хамгаалалт гаднах гэмтэлд тогтвортой байхын тулд бүрэн нөөц шаардах нь бий.", "x": "ex"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.3. Тогтмол бүрэлдэхүүнтэй богино холболтын үед ГТ-ийн ханалт (тоон загварчлал, E k≈800 В)", "h": "Зураг 5.3. Тогтмол бүрэлдэхүүнтэй богино холболтын үед ГТ-ийн ханалт (тоон загварчлал, E<sub>k</sub>≈800 В)"}, {"t": "p", "s": "Жишээ 5.3. Жишээ 5.2-ын ГТ-ийн хугарлын цэгийн хүчдэл 800 В эсвэл 1200 В бол ханалт эхлэх хугацааг тооцъё. Мөн хоёрдогч хугацааны тогтмол T s=1 с бүхий TPY ГТ-д хамгаалалт ажиллах хугацаа t′=40 мс хүртэл ханалтгүй байх шилжилтийн коэффициентыг олъё.", "h": "<b>Жишээ 5.3.</b> Жишээ 5.2-ын ГТ-ийн хугарлын цэгийн хүчдэл 800 В эсвэл 1200 В бол ханалт эхлэх хугацааг тооцъё. Мөн хоёрдогч хугацааны тогтмол T<sub>s</sub>=1 с бүхий TPY ГТ-д хамгаалалт ажиллах хугацаа t′=40 мс хүртэл ханалтгүй байх шилжилтийн коэффициентыг олъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (5.9)-өөр E k=800 В: K s=800/133.3=6.0; (5.10)-аар t s=−47.7ln(1−5/15)=−47.7⋅(−0.405)=19.4 мс. E k=1200 В: K s=9.0, t s=−47.7ln(1−8/15)=36.4 мс. Тоон загварчлалаар (Зураг 5.3) 800 В-ын ГТ 28 мс орчимд ханаж эхэлдэг нь (5.10)-ын үнэлгээ нөөцтэй болохыг харуулна. Ханасны дараа хоёрдогч гүйдэл үе бүрийн тодорхой хэсэгт «тасарч», үйлчлэх утга нь 30–60 % хүртэл буурна.", "h": "<i>Бодолт.</i> (5.9)-өөр E<sub>k</sub>=800 В: K<sub>s</sub>=800/133.3=6.0; (5.10)-аар t<sub>s</sub>=−47.7ln(1−5/15)=−47.7⋅(−0.405)=19.4 мс. E<sub>k</sub>=1200 В: K<sub>s</sub>=9.0, t<sub>s</sub>=−47.7ln(1−8/15)=36.4 мс. Тоон загварчлалаар (Зураг 5.3) 800 В-ын ГТ 28 мс орчимд ханаж эхэлдэг нь (5.10)-ын үнэлгээ нөөцтэй болохыг харуулна. Ханасны дараа хоёрдогч гүйдэл үе бүрийн тодорхой хэсэгт «тасарч», үйлчлэх утга нь 30–60 % хүртэл буурна.", "x": "ex"}, {"t": "p", "s": "TPY ГТ-ийн шилжилтийн коэффициент (IEC 61869-2-ын хялбаршуулсан илэрхийлэл):", "h": "TPY ГТ-ийн шилжилтийн коэффициент (IEC 61869-2-ын хялбаршуулсан илэрхийлэл):", "x": "ex"}, {"t": "eq", "s": "K td=(ωT 1T s)/(T s−T 1)(e^−t′/T s−e^−t′/T 1)+1 (5.11)", "h": "K<sub>td</sub>=(ωT<sub>1</sub>T<sub>s</sub>)/(T<sub>s</sub>−T<sub>1</sub>)(e<sup>−t′/T<sub>s</sub></sup>−e<sup>−t′/T<sub>1</sub></sup>)+1", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>K</mi><mrow><mi>t</mi><mi>d</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>ω</mi><msub><mi>T</mi><mn>1</mn></msub><msub><mi>T</mi><mi>s</mi></msub></mrow><mrow><msub><mi>T</mi><mi>s</mi></msub><mo>−</mo><msub><mi>T</mi><mn>1</mn></msub></mrow></mfrac><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi>′</mi><mi>/</mi><msub><mi>T</mi><mi>s</mi></msub></mrow></msup><mo>−</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi>′</mi><mi>/</mi><msub><mi>T</mi><mn>1</mn></msub></mrow></msup><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>+</mo><mn>1</mn></mrow></semantics></math>", "n": "5.11", "x": "ex"}, {"t": "p", "s": "Орлуулбал K td=(314.16⋅0.0477)/(1−0.0477)(e^−0.04−e^−0.838)+1=15.74⋅(0.961−0.433)+1=9.32. Шаардлагатай хүчдэл E k≈9.32⋅133.3=1243 В. Иймээс 40 мс-д ажиллах хамгаалалтад 1250–1300 В-ын хугарлын цэгтэй TPY ГТ хүрэлцэнэ; энэ нь (5.8)-ын бүрэн нөөц (2133 В)-өөс 40 % бага.", "h": "Орлуулбал K<sub>td</sub>=(314.16⋅0.0477)/(1−0.0477)(e<sup>−0.04</sup>−e<sup>−0.838</sup>)+1=15.74⋅(0.961−0.433)+1=9.32. Шаардлагатай хүчдэл E<sub>k</sub>≈9.32⋅133.3=1243 В. Иймээс 40 мс-д ажиллах хамгаалалтад 1250–1300 В-ын хугарлын цэгтэй TPY ГТ хүрэлцэнэ; энэ нь (5.8)-ын бүрэн нөөц (2133 В)-өөс 40 % бага.", "x": "ex"}, {"t": "h", "l": 2, "s": "2.5.\nХаналтын хамгаалалтад үзүүлэх нөлөө ба арга хэмжээ", "h": "2.5.\nХаналтын хамгаалалтад үзүүлэх нөлөө ба арга хэмжээ"}, {"t": "p", "s": "ГТ-ийн ханалт нь хамгаалалтын дараах буруу ажиллагааг үүсгэнэ: (1) максимал гүйдлийн хамгаалалт хоёрдогч гүйдлийн үйлчлэх утга буурснаас удааширна; (2) зайн хамгаалалт эсэргүүцлийг их хэмжиж, бүсээ багасгана (underreach); (3) дифференциал хамгаалалт гаднах гэмтлийн үед нэг талын ГТ ханахад хуурамч дифференциал гүйдэл үүсч, буруу ажиллана; (4) таслуурын гацалтын хамгаалалт гүйдэл тасарсны дараа ГТ-ийн хоёрдогчид удаан унтрах гүйдлээр (subsidence current) буруу дохио авна.", "h": "ГТ-ийн ханалт нь хамгаалалтын дараах буруу ажиллагааг үүсгэнэ: (1) <b>максимал гүйдлийн хамгаалалт</b> хоёрдогч гүйдлийн үйлчлэх утга буурснаас удааширна; (2) <b>зайн хамгаалалт</b> эсэргүүцлийг их хэмжиж, бүсээ багасгана (underreach); (3) <b>дифференциал хамгаалалт</b> гаднах гэмтлийн үед нэг талын ГТ ханахад хуурамч дифференциал гүйдэл үүсч, буруу ажиллана; (4) <b>таслуурын гацалтын хамгаалалт</b> гүйдэл тасарсны дараа ГТ-ийн хоёрдогчид удаан унтрах гүйдлээр (subsidence current) буруу дохио авна."}, {"t": "p", "s": "Ханалтын нөлөөг бууруулах арга хэмжээнүүд: хугарлын цэгийн хүчдэлийг (5.8)-аар хангах; хоёрдогч гүйдлийг 1 А сонгож холболтын утасны ачааллыг 25 дахин бууруулах; кабелийн огтлолыг нэмэгдүүлэх; агаарын завсартай TPY/TPZ цөм хэрэглэх; хамгаалалтын терминалд ханалт илрүүлэгч алгоритм (гармоник, гүйдлийн деривативын шинжилгээ) идэвхжүүлэх. Хамгийн үндсэн шийдэл нь ханалтгүй мэдрэгч (Роговскийн ороомог, оптик ГТ) хэрэглэх юм (§4).", "h": "Ханалтын нөлөөг бууруулах арга хэмжээнүүд: хугарлын цэгийн хүчдэлийг (5.8)-аар хангах; хоёрдогч гүйдлийг 1 А сонгож холболтын утасны ачааллыг 25 дахин бууруулах; кабелийн огтлолыг нэмэгдүүлэх; агаарын завсартай TPY/TPZ цөм хэрэглэх; хамгаалалтын терминалд ханалт илрүүлэгч алгоритм (гармоник, гүйдлийн деривативын шинжилгээ) идэвхжүүлэх. Хамгийн үндсэн шийдэл нь ханалтгүй мэдрэгч (Роговскийн ороомог, оптик ГТ) хэрэглэх юм (§4)."}, {"t": "h", "l": 1, "s": "3. Хүчдэлийн трансформатор", "h": "3. Хүчдэлийн трансформатор"}, {"t": "h", "l": 2, "s": "3.1. Индуктив ХТ ба\nнарийвчлалын анги", "h": "3.1. Индуктив ХТ ба\nнарийвчлалын анги"}, {"t": "p", "s": "Индуктив ХТ нь бага чадлын, сул явалтад ойр ажилладаг трансформатор бөгөөд 6–220 кВ-д хэрэглэгдэнэ. Хүчдэлийн алдаа", "h": "Индуктив ХТ нь бага чадлын, сул явалтад ойр ажилладаг трансформатор бөгөөд 6–220 кВ-д хэрэглэгдэнэ. Хүчдэлийн алдаа"}, {"t": "eq", "s": "ε u=(K nU 2−U 1)/U 1⋅100 % (5.12)", "h": "ε<sub>u</sub>=(K<sub>n</sub>U<sub>2</sub>−U<sub>1</sub>)/U<sub>1</sub>⋅100 %", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε</mi><mi>u</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>K</mi><mi>n</mi></msub><msub><mi>U</mi><mn>2</mn></msub><mo>−</mo><msub><mi>U</mi><mn>1</mn></msub></mrow><msub><mi>U</mi><mn>1</mn></msub></mfrac><mo>⋅</mo><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>%</mi></mrow></semantics></math>", "n": "5.12"}, {"t": "p", "s": "нь ороомгийн эсэргүүцэл, сарнилын индукцлэл дээрх хүчдэлийн уналтаас үүсдэг тул ачаалал өсөхөд нэмэгдэнэ. Хэмжүүрийн ангийн алдааг нэрлэсэн хүчдэлийн 80–120 %, ачааллын 25–100 %-д, хамгаалалтын ангийнхыг 5 %-иас хүчдэлийн коэффициент k u (1.2; 1.5; 1.9) хүртэл баталгаажуулна (Хүснэгт 5.4). Тусгаарлагдсан нейтральтай 6–35 кВ-ын сүлжээнд газардлагын гэмтлийн үед эрүүл фазын хүчдэл √(3) дахин өсдөг тул ХТ-ийн хүчдэлийн коэффициент 1.9 (8 ц) байх ёстой.", "h": "нь ороомгийн эсэргүүцэл, сарнилын индукцлэл дээрх хүчдэлийн уналтаас үүсдэг тул ачаалал өсөхөд нэмэгдэнэ. Хэмжүүрийн ангийн алдааг нэрлэсэн хүчдэлийн 80–120 %, ачааллын 25–100 %-д, хамгаалалтын ангийнхыг 5 %-иас хүчдэлийн коэффициент k<sub>u</sub> (1.2; 1.5; 1.9) хүртэл баталгаажуулна (Хүснэгт 5.4). Тусгаарлагдсан нейтральтай 6–35 кВ-ын сүлжээнд газардлагын гэмтлийн үед эрүүл фазын хүчдэл √(3) дахин өсдөг тул ХТ-ийн хүчдэлийн коэффициент 1.9 (8 ц) байх ёстой."}, {"t": "cap", "s": "Хүснэгт 5.4. ХТ-ийн нарийвчлалын анги (IEC 61869-3, -5)", "h": "Хүснэгт 5.4. ХТ-ийн нарийвчлалын анги (IEC 61869-3, -5)"}, {"t": "tbl", "s": "", "head": ["Анги", "Хүчдэлийн алдаа, ±%", "Фазын шилжилт, ±мин", "Хэрэглээ"], "rows": [["0.1", "0.1", "5", "Лабораторийн, эталон"], ["0.2", "0.2", "10", "Арилжааны тоолуур (110–220 кВ)"], ["0.5", "0.5", "20", "Техникийн тоолуур, хэмжилт"], ["1.0", "1.0", "40", "Үзүүлэх хэрэгсэл"], ["3P", "3.0", "120", "Хамгаалалт"], ["6P", "6.0", "240", "Хамгаалалт"]]}, {"t": "h", "l": 2, "s": "3.2. Индуктив ХТ-ийн\nферрорезонанс", "h": "3.2. Индуктив ХТ-ийн\nферрорезонанс"}, {"t": "p", "s": "Феррорезонанс нь ХТ-ийн шугаман бус индукцлэл ба сүлжээний багтаамж (кабель, шина, таслуурын контактыг шунтлах конденсатор, тусгаарлагдсан нейтральтай сүлжээний газартай багтаамж) хооронд үүсдэг, хэт хүчдэл ба хэт гүйдэл дагалддаг тогтвортой хэлбэлзэл юм. Энгийн LC хэлхээнээс ялгаатай нь цөмийн ханалтаас болж индукцлэл гүйдлээс хамаардаг тул нэг параметрийн хувьд хэд хэдэн тогтвортой горим оршин байж болно.", "h": "<b>Феррорезонанс</b> нь ХТ-ийн шугаман бус индукцлэл ба сүлжээний багтаамж (кабель, шина, таслуурын контактыг шунтлах конденсатор, тусгаарлагдсан нейтральтай сүлжээний газартай багтаамж) хооронд үүсдэг, хэт хүчдэл ба хэт гүйдэл дагалддаг тогтвортой хэлбэлзэл юм. Энгийн LC хэлхээнээс ялгаатай нь цөмийн ханалтаас болж индукцлэл гүйдлээс хамаардаг тул нэг параметрийн хувьд хэд хэдэн тогтвортой горим оршин байж болно."}, {"t": "p", "s": "Цуваа хэлхээнд E эх үүсвэр, X C багтаамж, ХТ-ийн U L(I) шугаман бус индукцлэл холбогдсон гэж үзье. Индукцлэл ба багтаамжийн хүчдэл эсрэг фазтай тул горимын тэгшитгэл:", "h": "Цуваа хэлхээнд E эх үүсвэр, X<sub>C</sub> багтаамж, ХТ-ийн U<sub>L</sub>(I) шугаман бус индукцлэл холбогдсон гэж үзье. Индукцлэл ба багтаамжийн хүчдэл эсрэг фазтай тул горимын тэгшитгэл:"}, {"t": "eq", "s": "U L(I)=E+I X C (индуктив), U L(I)=I X C−E (багтаамжийн) (5.13)", "h": "U<sub>L</sub>(I)=E+I X<sub>C</sub> (индуктив), U<sub>L</sub>(I)=I X<sub>C</sub>−E (багтаамжийн)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>L</mi></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>I</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><mi>E</mi><mo>+</mo><mi>I</mi><mspace width=\"0.167em\"></mspace><msub><mi>X</mi><mi>C</mi></msub><mspace width=\"1.0em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mtext mathvariant=\"normal\">индуктив</mtext><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>U</mi><mi>L</mi></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>I</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><mi>I</mi><mspace width=\"0.167em\"></mspace><msub><mi>X</mi><mi>C</mi></msub><mo>−</mo><mi>E</mi><mspace width=\"1.0em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mtext mathvariant=\"normal\">багтаамжийн</mtext><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "5.13"}, {"t": "p", "s": "Зураг 5.4-ийн график шийдэлд гурван цэг гарна: 1 — хэвийн, индуктив горим (бага гүйдэл); 2 — тогтворгүй; 3 — феррорезонансын багтаамжийн горим (гүйдэл хэвийнээс олон дахин их, ХТ-ийн хүчдэл ханалтын түвшинд). Хэвийн горимоос 3-р горим руу «үсрэх» нь коммутац, газардлагын гэмтэл, нэг фаз тасрах зэрэг шилжилтийн процессоор өдөөгдөнө. Феррорезонанс үүсэх нөхцөл ойролцоогоор ωL ханалт<X C<ωL шугаман юм.", "h": "Зураг 5.4-ийн график шийдэлд гурван цэг гарна: <b>1</b> — хэвийн, индуктив горим (бага гүйдэл); <b>2</b> — тогтворгүй; <b>3</b> — феррорезонансын багтаамжийн горим (гүйдэл хэвийнээс олон дахин их, ХТ-ийн хүчдэл ханалтын түвшинд). Хэвийн горимоос 3-р горим руу «үсрэх» нь коммутац, газардлагын гэмтэл, нэг фаз тасрах зэрэг шилжилтийн процессоор өдөөгдөнө. Феррорезонанс үүсэх нөхцөл ойролцоогоор ωL<sub>ханалт</sub>&lt;X<sub>C</sub>&lt;ωL<sub>шугаман</sub> юм."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.4. Феррорезонансын график шийдэл (х.н. — харьцангуй нэгж)", "h": "Зураг 5.4. Феррорезонансын график шийдэл (х.н. — харьцангуй нэгж)"}, {"t": "p", "s": "Монголын 6–10 кВ-ын тусгаарлагдсан нейтральтай хот, уурхайн түгээх сүлжээнд газардлагын нумын гэмтлийн дараа НТМИ, ЗНОЛ төрлийн ХТ-ийн анхдагч гал хамгаалагч тасрах, ХТ шатах тохиолдол түгээмэл байдаг нь феррорезонансын шинж юм. Үүнийг бууруулах арга хэмжээ: (1) ХТ-ийн нээлттэй гурвалжин ороомогт 25–50 Ом-ын сааруулах резистор холбох; (2) ХТ-ийн анхдагч нейтральд тусгай резистор эсвэл нэг фазын нэмэлт ХТ холбох; (3) соронзон индукцийг багасгасан антирезонансын ХТ (НАМИ төрлийн) хэрэглэх; (4) нейтралыг нумын реактор эсвэл резистороор газардуулах; (5) LPVT (резистив хуваагч) хэрэглэх — төмөр цөмгүй тул феррорезонанс үүсэх боломжгүй. 110–220 кВ-д феррорезонанс голчлон таслуурын шунт конденсатор ба шинын индуктив ХТ хооронд таслуур нээгдсэн үед үүсдэг.", "h": "Монголын 6–10 кВ-ын тусгаарлагдсан нейтральтай хот, уурхайн түгээх сүлжээнд газардлагын нумын гэмтлийн дараа НТМИ, ЗНОЛ төрлийн ХТ-ийн анхдагч гал хамгаалагч тасрах, ХТ шатах тохиолдол түгээмэл байдаг нь феррорезонансын шинж юм. Үүнийг бууруулах арга хэмжээ: (1) ХТ-ийн нээлттэй гурвалжин ороомогт 25–50 Ом-ын сааруулах резистор холбох; (2) ХТ-ийн анхдагч нейтральд тусгай резистор эсвэл нэг фазын нэмэлт ХТ холбох; (3) соронзон индукцийг багасгасан антирезонансын ХТ (НАМИ төрлийн) хэрэглэх; (4) нейтралыг нумын реактор эсвэл резистороор газардуулах; (5) LPVT (резистив хуваагч) хэрэглэх — төмөр цөмгүй тул феррорезонанс үүсэх боломжгүй. 110–220 кВ-д феррорезонанс голчлон таслуурын шунт конденсатор ба шинын индуктив ХТ хооронд таслуур нээгдсэн үед үүсдэг."}, {"t": "h", "l": 2, "s": "3.3. Багтаамжийн\nхүчдэлийн трансформатор (CVT)", "h": "3.3. Багтаамжийн\nхүчдэлийн трансформатор (CVT)"}, {"t": "p", "s": "110 кВ ба түүнээс дээш хүчдэлд индуктив ХТ-ийн тусгаарлага, жин, өртөг огцом өсдөг тул багтаамжийн ХТ (CVT) өргөн хэрэглэгдэнэ. CVT нь багтаамжийн хуваагч (C 1, C 2), тааруулах реактор L, завсрын индуктив ХТ, феррорезонанс сааруулах хэлхээнээс бүрдэнэ (Зураг 5.5). Хуваагчийн завсрын хүчдэл:", "h": "110 кВ ба түүнээс дээш хүчдэлд индуктив ХТ-ийн тусгаарлага, жин, өртөг огцом өсдөг тул <b>багтаамжийн ХТ</b> (CVT) өргөн хэрэглэгдэнэ. CVT нь багтаамжийн хуваагч (C<sub>1</sub>, C<sub>2</sub>), тааруулах реактор L, завсрын индуктив ХТ, феррорезонанс сааруулах хэлхээнээс бүрдэнэ (Зураг 5.5). Хуваагчийн завсрын хүчдэл:"}, {"t": "eq", "s": "U i=U 1 C 1/(C 1+C 2) (5.14)", "h": "U<sub>i</sub>=U<sub>1</sub> C<sub>1</sub>/(C<sub>1</sub>+C<sub>2</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>i</mi></msub><mo>=</mo><msub><mi>U</mi><mn>1</mn></msub><mspace width=\"0.167em\"></mspace><mfrac><msub><mi>C</mi><mn>1</mn></msub><mrow><msub><mi>C</mi><mn>1</mn></msub><mo>+</mo><msub><mi>C</mi><mn>2</mn></msub></mrow></mfrac></mrow></semantics></math>", "n": "5.14"}, {"t": "p", "s": "Ачаалал өсөхөд хуваагчийн дотоод эсэргүүцэл (C 1+C 2-ийн багтаамжийн эсэргүүцэл) дээр хүчдэл унаж, алдаа үүснэ. Үүнийг нөхөхийн тулд тааруулах реакторыг нэрлэсэн давтамжид багтаамжтай резонанст тохируулна:", "h": "Ачаалал өсөхөд хуваагчийн дотоод эсэргүүцэл (C<sub>1</sub>+C<sub>2</sub>-ийн багтаамжийн эсэргүүцэл) дээр хүчдэл унаж, алдаа үүснэ. Үүнийг нөхөхийн тулд тааруулах реакторыг нэрлэсэн давтамжид багтаамжтай резонанст тохируулна:"}, {"t": "eq", "s": "ω^2L (C 1+C 2)=1 ⇒ L=1/(ω^2(C 1+C 2)) (5.15)", "h": "ω<sup>2</sup>L (C<sub>1</sub>+C<sub>2</sub>)=1  ⇒  L=1/(ω<sup>2</sup>(C<sub>1</sub>+C<sub>2</sub>))", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ω</mi><mn>2</mn></msup><mi>L</mi><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>C</mi><mn>1</mn></msub><mo>+</mo><msub><mi>C</mi><mn>2</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><mn>1</mn><mspace width=\"0.278em\"></mspace><mspace width=\"0.278em\"></mspace><mo>⇒</mo><mspace width=\"0.278em\"></mspace><mspace width=\"0.278em\"></mspace><mi>L</mi><mo>=</mo><mfrac><mn>1</mn><mrow><msup><mi>ω</mi><mn>2</mn></msup><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>C</mi><mn>1</mn></msub><mo>+</mo><msub><mi>C</mi><mn>2</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></mfrac></mrow></semantics></math>", "n": "5.15"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.5. Багтаамжийн хүчдэлийн трансформаторын (CVT) зарчмын схем", "h": "Зураг 5.5. Багтаамжийн хүчдэлийн трансформаторын (CVT) зарчмын схем"}, {"t": "p", "s": "CVT-ийн хязгаарлалтууд: (1) давтамж нэрлэснээс хазайхад резонансын тохируулга алдагдаж алдаа өсдөг тул гармоник хэмжилтэд тохиромжгүй (Зураг 5.8, б); (2) богино холболтын үед хүчдэл огцом буурахад хуваагч, реакторт хуримтлагдсан энерги шилжилтийн хүчдэл (transient response) үүсгэж, хурдан ажилладаг зайн хамгаалалтын хэмжилтийг 1–2 үеийн турш гажуудуулдаг; (3) завсрын ХТ-д феррорезонанс үүсэх эрсдэлтэй тул сааруулах хэлхээ заавал байна. CVT-ийн давуу тал нь өндөр давтамжийн холбооны (PLC) холболтын конденсаторын үүргийг давхар гүйцэтгэдэг явдал юм.", "h": "CVT-ийн хязгаарлалтууд: (1) давтамж нэрлэснээс хазайхад резонансын тохируулга алдагдаж алдаа өсдөг тул гармоник хэмжилтэд тохиромжгүй (Зураг 5.8, б); (2) богино холболтын үед хүчдэл огцом буурахад хуваагч, реакторт хуримтлагдсан энерги шилжилтийн хүчдэл (transient response) үүсгэж, хурдан ажилладаг зайн хамгаалалтын хэмжилтийг 1–2 үеийн турш гажуудуулдаг; (3) завсрын ХТ-д феррорезонанс үүсэх эрсдэлтэй тул сааруулах хэлхээ заавал байна. CVT-ийн давуу тал нь өндөр давтамжийн холбооны (PLC) холболтын конденсаторын үүргийг давхар гүйцэтгэдэг явдал юм."}, {"t": "p", "s": "Жишээ 5.4. 110 кВ-ын CVT-ийн C 1=5 нФ, C 2=55 нФ. Завсрын хүчдэл, тааруулах реакторын индукцлэл, завсрын ХТ-ийн хувиргалтын коэффициентыг тодорхойлъё.", "h": "<b>Жишээ 5.4.</b> 110 кВ-ын CVT-ийн C<sub>1</sub>=5 нФ, C<sub>2</sub>=55 нФ. Завсрын хүчдэл, тааруулах реакторын индукцлэл, завсрын ХТ-ийн хувиргалтын коэффициентыг тодорхойлъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. Фазын хүчдэл U 1=110/√(3)=63.51 кВ. (5.14)-өөр U i=63.51⋅5/(5+55)=5.29 кВ. (5.15)-аар L=1/[(2π⋅50)^2⋅60⋅10^−9]=1/(98 696⋅60⋅10^−9)=168.9 Гн. Завсрын ХТ-ийн коэффициент K=5292/(100/√(3))=91.7.", "h": "<i>Бодолт.</i> Фазын хүчдэл U<sub>1</sub>=110/√(3)=63.51 кВ. (5.14)-өөр U<sub>i</sub>=63.51⋅5/(5+55)=5.29 кВ. (5.15)-аар L=1/[(2π⋅50)<sup>2</sup>⋅60⋅10<sup>−9</sup>]=1/(98 696⋅60⋅10<sup>−9</sup>)=168.9 Гн. Завсрын ХТ-ийн коэффициент K=5292/(100/√(3))=91.7.", "x": "ex"}, {"t": "h", "l": 1, "s": "4. Уламжлалт\nбус (бага чадлын) хэмжүүрийн трансформатор", "h": "4. Уламжлалт\nбус (бага чадлын) хэмжүүрийн трансформатор"}, {"t": "p", "s": "Ферросоронзон цөмтэй хэмжүүрийн трансформаторын үндсэн хязгаарлалт — ханалт, феррорезонанс, хязгаарлагдмал давтамжийн зурвас, тосон тусгаарлагын дэлбэрэх эрсдэл, их жин — нь цөмгүй, бага чадлын мэдрэгч рүү шилжих түлхэц болсон.", "h": "Ферросоронзон цөмтэй хэмжүүрийн трансформаторын үндсэн хязгаарлалт — ханалт, феррорезонанс, хязгаарлагдмал давтамжийн зурвас, тосон тусгаарлагын дэлбэрэх эрсдэл, их жин — нь цөмгүй, бага чадлын мэдрэгч рүү шилжих түлхэц болсон."}, {"t": "h", "l": 2, "s": "4.1. Оптик\nгүйдлийн трансформатор (Фарадейн эффект)", "h": "4.1. Оптик\nгүйдлийн трансформатор (Фарадейн эффект)"}, {"t": "p", "s": "Шугаман туйлширсан гэрэл соронзон орон дахь тунгалаг орчинд соронзон орны чиглэлд тархахад туйлшралын хавтгай эргэдэг үзэгдлийг Фарадейн эффект гэнэ. Гэрлийн замын дагуу эргэлтийн өнцөг:", "h": "Шугаман туйлширсан гэрэл соронзон орон дахь тунгалаг орчинд соронзон орны чиглэлд тархахад туйлшралын хавтгай эргэдэг үзэгдлийг <b>Фарадейн эффект</b> гэнэ. Гэрлийн замын дагуу эргэлтийн өнцөг:"}, {"t": "eq", "s": "θ=V∫ l𝐁⋅d𝐥=Vμ 0∮𝐇⋅d𝐥=Vμ 0 N I (5.16)", "h": "θ=V∫<sub>l</sub>𝐁⋅d𝐥=Vμ<sub>0</sub>∮𝐇⋅d𝐥=Vμ<sub>0</sub> N I", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi><mo>=</mo><mi>V</mi><msub><mo>∫</mo><mi>l</mi></msub><mi>𝐁</mi><mo>⋅</mo><mi>d</mi><mi>𝐥</mi><mo>=</mo><mi>V</mi><msub><mi>μ</mi><mn>0</mn></msub><mo>∮</mo><mi>𝐇</mi><mo>⋅</mo><mi>d</mi><mi>𝐥</mi><mo>=</mo><mi>V</mi><msub><mi>μ</mi><mn>0</mn></msub><mspace width=\"0.167em\"></mspace><mi>N</mi><mspace width=\"0.167em\"></mspace><mi>I</mi></mrow></semantics></math>", "n": "5.16"}, {"t": "p", "s": "энд V — Верде тогтмол, рад/(Тл·м); N — гүйдэлтэй дамжуулагчийг тойрох шилэн утасны эргэлтийн тоо. Гэрлийн зам дамжуулагчийг битүү тойрсон үед Амперын хуулиар интеграл нь зөвхөн тойрсон гүйдлээс хамаарах ба зэргэлдээ фазын гүйдэл, дамжуулагчийн байрлалд мэдрэмтгий бус болно. Энэ нь битүү хүрээтэй оптик ГТ-ийн гол давуу тал юм.", "h": "энд V — Верде тогтмол, рад/(Тл·м); N — гүйдэлтэй дамжуулагчийг тойрох шилэн утасны эргэлтийн тоо. Гэрлийн зам дамжуулагчийг <b>битүү</b> тойрсон үед Амперын хуулиар интеграл нь зөвхөн тойрсон гүйдлээс хамаарах ба зэргэлдээ фазын гүйдэл, дамжуулагчийн байрлалд мэдрэмтгий бус болно. Энэ нь битүү хүрээтэй оптик ГТ-ийн гол давуу тал юм."}, {"t": "p", "s": "Орчин үеийн шилэн утсан оптик ГТ (Fiber-Optic Current Sensor, FOCS) нь ихэвчлэн ойлгогч Саньякийн (reflective Sagnac) интерферометрийн бүтэцтэй (Зураг 5.6). Гэрлийн эх үүсвэрээс (SLED) гарсан гэрэл туйлшруулагч, фазын модулятороор дамжиж, туйлшрал хадгалах шилэн кабелиар өндөр хүчдэлийн тал руу очно. Тэнд λ/4 хавтан шугаман туйлшралыг баруун ба зүүн тойрог туйлшралд хувиргаж, мэдрэгч ороомгоор дамжуулаад, төгсгөлийн толиноос ойж буцна. Хоёр тойрог туйлшралын хоорондох Фарадейн фазын зөрүү:", "h": "Орчин үеийн шилэн утсан оптик ГТ (Fiber-Optic Current Sensor, FOCS) нь ихэвчлэн <b>ойлгогч Саньякийн</b> (reflective Sagnac) интерферометрийн бүтэцтэй (Зураг 5.6). Гэрлийн эх үүсвэрээс (SLED) гарсан гэрэл туйлшруулагч, фазын модулятороор дамжиж, туйлшрал хадгалах шилэн кабелиар өндөр хүчдэлийн тал руу очно. Тэнд λ/4 хавтан шугаман туйлшралыг баруун ба зүүн тойрог туйлшралд хувиргаж, мэдрэгч ороомгоор дамжуулаад, төгсгөлийн толиноос ойж буцна. Хоёр тойрог туйлшралын хоорондох Фарадейн фазын зөрүү:"}, {"t": "eq", "s": "Δφ=4 V μ N I, V μ=μ 0V (5.17)", "h": "Δφ=4 V<sub>μ</sub> N I, V<sub>μ</sub>=μ<sub>0</sub>V", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>φ</mi><mo>=</mo><mn>4</mn><mspace width=\"0.167em\"></mspace><msub><mi>V</mi><mi>μ</mi></msub><mspace width=\"0.167em\"></mspace><mi>N</mi><mspace width=\"0.167em\"></mspace><mi>I</mi><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>V</mi><mi>μ</mi></msub><mo>=</mo><msub><mi>μ</mi><mn>0</mn></msub><mi>V</mi></mrow></semantics></math>", "n": "5.17"}, {"t": "p", "s": "Энд 4-ийн коэффициент нь хоёр тойрог туйлшралын эсрэг эргэлт (×2) ба ойлтоор хоёр дахин дамжих (×2)-ээс үүснэ. Кварцан шилэн утсанд 1310 нм долгионы уртад V μ≈1 мкрад/А орчим байдаг.", "h": "Энд 4-ийн коэффициент нь хоёр тойрог туйлшралын эсрэг эргэлт (×2) ба ойлтоор хоёр дахин дамжих (×2)-ээс үүснэ. Кварцан шилэн утсанд 1310 нм долгионы уртад V<sub>μ</sub>≈1 мкрад/А орчим байдаг."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.6. Шилэн утсан оптик ГТ-ийн (ойлгогч Саньякийн интерферометр) бүтцийн схем", "h": "Зураг 5.6. Шилэн утсан оптик ГТ-ийн (ойлгогч Саньякийн интерферометр) бүтцийн схем"}, {"t": "p", "s": "Оптик ГТ-ийн давуу тал: ханалтгүй, шугаман (нэрлэсний 1 %-иас 100 дахин хүртэл нэг мэдрэгчээр хэмжинэ), давтамжийн зурвас тогтмол гүйдлээс хэдэн кГц хүртэл, өндөр хүчдэлийн тал бүрэн идэвхгүй (тэжээл, электроникгүй), тос, SF6 байхгүй тул дэлбэрэх, гал гарах аюулгүй, жин бага (110 кВ-ын тосон ГТ 500–800 кг бол оптик ГТ-ийн мэдрэгч хэдэн арван кг), таслуурын оролт, КРУЭ/GIS-ийн фланц эсвэл тулгуур тусгаарлагчид нэгтгэж болно. Сул тал: Верде тогтмол ба шилэн утасны хугарлын шинж чанар температураас хамаардаг (кварцанд ≈0.7⋅10^−4 1/К), механик чичиргээ, шилэн утасны гулзайлтын хүчдэлд мэдрэмтгий тул тусгай нөхөн олговор шаарддаг; электроник нь хяналтын байранд тэжээл, хөргөлт шаардана; үнэ өндөр. Монголын −40 °C-оос +40 °C-ийн температурын 80 К хүрээнд нөхөн олговоргүй Верде тогтмол 0.56 % орчим өөрчлөгддөг нь 0.2 ангийн шаардлагыг давж байгаа тул үйлдвэрлэгч λ/4 хавтангийн температурын шинжийг ашиглан нөхөн олговор хийсэн эсэхийг заавал шалгах хэрэгтэй.", "h": "Оптик ГТ-ийн давуу тал: ханалтгүй, шугаман (нэрлэсний 1 %-иас 100 дахин хүртэл нэг мэдрэгчээр хэмжинэ), давтамжийн зурвас тогтмол гүйдлээс хэдэн кГц хүртэл, өндөр хүчдэлийн тал бүрэн идэвхгүй (тэжээл, электроникгүй), тос, SF6 байхгүй тул дэлбэрэх, гал гарах аюулгүй, жин бага (110 кВ-ын тосон ГТ 500–800 кг бол оптик ГТ-ийн мэдрэгч хэдэн арван кг), таслуурын оролт, КРУЭ/GIS-ийн фланц эсвэл тулгуур тусгаарлагчид нэгтгэж болно. Сул тал: Верде тогтмол ба шилэн утасны хугарлын шинж чанар температураас хамаардаг (кварцанд ≈0.7⋅10<sup>−4</sup> 1/К), механик чичиргээ, шилэн утасны гулзайлтын хүчдэлд мэдрэмтгий тул тусгай нөхөн олговор шаарддаг; электроник нь хяналтын байранд тэжээл, хөргөлт шаардана; үнэ өндөр. Монголын −40 °C-оос +40 °C-ийн температурын 80 К хүрээнд нөхөн олговоргүй Верде тогтмол 0.56 % орчим өөрчлөгддөг нь 0.2 ангийн шаардлагыг давж байгаа тул үйлдвэрлэгч λ/4 хавтангийн температурын шинжийг ашиглан нөхөн олговор хийсэн эсэхийг заавал шалгах хэрэгтэй."}, {"t": "p", "s": "Жишээ 5.5. 220 кВ-ын шугамын оптик ГТ-ийн мэдрэгч ороомог N=3 эргэлттэй, V μ=1.0 мкрад/А. Нэрлэсэн гүйдэл 1000 ба 2000 А, богино холболтын гүйдэл 40 кА-ийн далайцад харгалзах фазын зөрүүг тооцъё.", "h": "<b>Жишээ 5.5.</b> 220 кВ-ын шугамын оптик ГТ-ийн мэдрэгч ороомог N=3 эргэлттэй, V<sub>μ</sub>=1.0 мкрад/А. Нэрлэсэн гүйдэл 1000 ба 2000 А, богино холболтын гүйдэл 40 кА-ийн далайцад харгалзах фазын зөрүүг тооцъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (5.17)-оор I=1000 А: Δφ=4⋅1.0⋅10^−6⋅3⋅1000=0.012 рад =0.69^∘. I=2000 А: 0.024 рад =1.38^∘. I=40 кА: 0.48 рад =27.5^∘. Нэрлэсэн гүйдэлд фазын зөрүү маш бага тул 0.2 ангийн нарийвчлалд хүрэхийн тулд микрорадианы түвшинд (≈ 2.4⋅10^−5 рад) ялгах чадвар шаардлагатай; иймээс фазын модуляц ба хаалттай хүрээтэй тэглэх аргаар хэмжинэ. Богино холболтын гүйдэлд фазын зөрүү 0.5 рад орчим болж, sinΔφ-ийн шугаман бус байдлыг электроникоор залруулна. Эргэлтийн тоог ихэсгэх нь мэдрэмжийг өсгөх боловч хэмжих дээд гүйдлийг багасгана.", "h": "<i>Бодолт.</i> (5.17)-оор I=1000 А: Δφ=4⋅1.0⋅10<sup>−6</sup>⋅3⋅1000=0.012 рад =0.69<sup>∘</sup>. I=2000 А: 0.024 рад =1.38<sup>∘</sup>. I=40 кА: 0.48 рад =27.5<sup>∘</sup>. Нэрлэсэн гүйдэлд фазын зөрүү маш бага тул 0.2 ангийн нарийвчлалд хүрэхийн тулд микрорадианы түвшинд (≈ 2.4⋅10<sup>−5</sup> рад) ялгах чадвар шаардлагатай; иймээс фазын модуляц ба хаалттай хүрээтэй тэглэх аргаар хэмжинэ. Богино холболтын гүйдэлд фазын зөрүү 0.5 рад орчим болж, sinΔφ-ийн шугаман бус байдлыг электроникоор залруулна. Эргэлтийн тоог ихэсгэх нь мэдрэмжийг өсгөх боловч хэмжих дээд гүйдлийг багасгана.", "x": "ex"}, {"t": "h", "l": 2, "s": "4.2. Роговскийн ороомог", "h": "4.2. Роговскийн ороомог"}, {"t": "p", "s": "Роговскийн ороомог нь соронзон бус (агаар, пластик) гол дээр жигд ороосон, дамжуулагчийг битүү тойрсон ороомог юм (Зураг 5.7). Ороомгийн буцах утсыг голын дотуур буцаан гаргаснаар ороомгийн хавтгайд перпендикуляр гадаад орны нөлөөг арилгана. Ороомогт индукцлэгдэх ЦХХ нь гүйдлийн уламжлалд пропорциональ:", "h": "Роговскийн ороомог нь соронзон бус (агаар, пластик) гол дээр жигд ороосон, дамжуулагчийг битүү тойрсон ороомог юм (Зураг 5.7). Ороомгийн буцах утсыг голын дотуур буцаан гаргаснаар ороомгийн хавтгайд перпендикуляр гадаад орны нөлөөг арилгана. Ороомогт индукцлэгдэх ЦХХ нь гүйдлийн уламжлалд пропорциональ:"}, {"t": "eq", "s": "e(t)=−M (di(t))/dt (5.18)", "h": "e(t)=−M (di(t))/dt", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e</mi><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><mo>−</mo><mi>M</mi><mspace width=\"0.167em\"></mspace><mfrac><mrow><mi>d</mi><mi>i</mi><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow><mrow><mi>d</mi><mi>t</mi></mrow></mfrac></mrow></semantics></math>", "n": "5.18"}, {"t": "p", "s": "Тэгш өнцөгт огтлолтой (дотоод радиус a, гадаад радиус b, өндөр h) N эргэлттэй ороомгийн харилцан индукцлэл:", "h": "Тэгш өнцөгт огтлолтой (дотоод радиус a, гадаад радиус b, өндөр h) N эргэлттэй ороомгийн харилцан индукцлэл:"}, {"t": "eq", "s": "M=(μ 0Nh)/2πlnb/a (5.19)", "h": "M=(μ<sub>0</sub>Nh)/2πlnb/a", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi><mo>=</mo><mfrac><mrow><msub><mi>μ</mi><mn>0</mn></msub><mi>N</mi><mi>h</mi></mrow><mrow><mn>2</mn><mi>π</mi></mrow></mfrac><mo>ln</mo><mfrac><mi>b</mi><mi>a</mi></mfrac></mrow></semantics></math>", "n": "5.19"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.7. Роговскийн ороомог: ерөнхий хэлбэр, огтлолын хэмжээ ба интеграторын хэлхээ", "h": "Зураг 5.7. Роговскийн ороомог: ерөнхий хэлбэр, огтлолын хэмжээ ба интеграторын хэлхээ"}, {"t": "p", "s": "Гүйдэлтэй пропорциональ дохио авахын тулд ЦХХ-ийг интегрална. RC интегратор эсвэл MU-ийн дижитал интеграторын гаралт:", "h": "Гүйдэлтэй пропорциональ дохио авахын тулд ЦХХ-ийг интегрална. RC интегратор эсвэл MU-ийн дижитал интеграторын гаралт:"}, {"t": "eq", "s": "u(t)=1/RC∫e dt=−M/RC i(t) (5.20)", "h": "u(t)=1/RC∫e dt=−M/RC i(t)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u</mi><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>=</mo><mfrac><mn>1</mn><mrow><mi>R</mi><mi>C</mi></mrow></mfrac><mo>∫</mo><mi>e</mi><mspace width=\"0.167em\"></mspace><mi>d</mi><mi>t</mi><mo>=</mo><mo>−</mo><mfrac><mi>M</mi><mrow><mi>R</mi><mi>C</mi></mrow></mfrac><mspace width=\"0.167em\"></mspace><mi>i</mi><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>t</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "5.20"}, {"t": "p", "s": "Синусоид гүйдлийн үед ЦХХ-ийн үйлчлэх утга E=ωMI бөгөөд 90°-аар хоцорно. Роговскийн ороомгийн давуу тал: ханалтгүй (цөмгүй), шугаман байдал маш өргөн хүрээнд (хэдэн ампераас хэдэн зуун кА хүртэл), давтамжийн зурвас өргөн (Гц-ээс МГц), жин бага, уян хувилбарыг одоо байгаа дамжуулагч дээр салгалгүй суурилуулж болно, хоёрдогч хэлхээ задрахад аюулгүй (бага хүчдэл). Сул тал: гаралтын дохио бага (милливольт), интеграторын шилжилт (drift), тогтмол бүрэлдэхүүнийг шууд хэмжихгүй (интегратор сэргээдэг), ороомгийн жигд бус байдал ба дамжуулагчийн байрлалаас хамаарах алдаа (0.1–1 %), температурын нөлөөгөөр хэмжээ өөрчлөгдөх, цахилгаан соронзон саадад мэдрэмтгий тул экранжуулсан кабель шаардлагатай.", "h": "Синусоид гүйдлийн үед ЦХХ-ийн үйлчлэх утга E=ωMI бөгөөд 90°-аар хоцорно. Роговскийн ороомгийн давуу тал: ханалтгүй (цөмгүй), шугаман байдал маш өргөн хүрээнд (хэдэн ампераас хэдэн зуун кА хүртэл), давтамжийн зурвас өргөн (Гц-ээс МГц), жин бага, уян хувилбарыг одоо байгаа дамжуулагч дээр салгалгүй суурилуулж болно, хоёрдогч хэлхээ задрахад аюулгүй (бага хүчдэл). Сул тал: гаралтын дохио бага (милливольт), интеграторын шилжилт (drift), тогтмол бүрэлдэхүүнийг шууд хэмжихгүй (интегратор сэргээдэг), ороомгийн жигд бус байдал ба дамжуулагчийн байрлалаас хамаарах алдаа (0.1–1 %), температурын нөлөөгөөр хэмжээ өөрчлөгдөх, цахилгаан соронзон саадад мэдрэмтгий тул экранжуулсан кабель шаардлагатай."}, {"t": "p", "s": "Жишээ 5.6. Роговскийн ороомог N=1000 эргэлт, h=10 мм, a=50 мм, b=70 мм. Харилцан индукцлэл, 1 кА ба 40 кА (50 Гц) гүйдэлд гаралтын ЦХХ-ийг олъё.", "h": "<b>Жишээ 5.6.</b> Роговскийн ороомог N=1000 эргэлт, h=10 мм, a=50 мм, b=70 мм. Харилцан индукцлэл, 1 кА ба 40 кА (50 Гц) гүйдэлд гаралтын ЦХХ-ийг олъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (5.19)-өөр M=(4π⋅10^−7⋅1000⋅0.01)/2πln70/50=2⋅10^−6⋅0.3365=0.673 мкГн. E=ωMI: 1 кА-д E=314.16⋅0.673⋅10^−6⋅1000=0.211 В; 40 кА-д E=8.46 В. Тиймээс нэг ороомог хэвийн ба богино холболтын гүйдлийг 1:40 харьцаагаар шугаман байдлаар хэмжих бөгөөд АЦХ-ын оролтын хүрээг (±10 В) тогтмол бүрэлдэхүүнтэй гүйдлийн оргилыг тооцож сонгоно: 40 кА-ийн тэгш хэмт гүйдлийн оргилд √(2)⋅8.46=11.96 В тул оролтод хуваагч хэрэгтэй.", "h": "<i>Бодолт.</i> (5.19)-өөр M=(4π⋅10<sup>−7</sup>⋅1000⋅0.01)/2πln70/50=2⋅10<sup>−6</sup>⋅0.3365=0.673 мкГн. E=ωMI: 1 кА-д E=314.16⋅0.673⋅10<sup>−6</sup>⋅1000=0.211 В; 40 кА-д E=8.46 В. Тиймээс нэг ороомог хэвийн ба богино холболтын гүйдлийг 1:40 харьцаагаар шугаман байдлаар хэмжих бөгөөд АЦХ-ын оролтын хүрээг (±10 В) тогтмол бүрэлдэхүүнтэй гүйдлийн оргилыг тооцож сонгоно: 40 кА-ийн тэгш хэмт гүйдлийн оргилд √(2)⋅8.46=11.96 В тул оролтод хуваагч хэрэгтэй.", "x": "ex"}, {"t": "h", "l": 2, "s": "4.3. Багтаамжийн ба\nэсэргүүцлийн хүчдэл хуваагч", "h": "4.3. Багтаамжийн ба\nэсэргүүцлийн хүчдэл хуваагч"}, {"t": "p", "s": "Бага чадлын хүчдэлийн трансформатор (LPVT) нь цөмгүй эсэргүүцлийн (R), багтаамжийн (C) эсвэл холимог (RC) хуваагч юм. Эсэргүүцлийн хуваагчийн хувиргалтын коэффициент:", "h": "Бага чадлын хүчдэлийн трансформатор (LPVT) нь цөмгүй эсэргүүцлийн (R), багтаамжийн (C) эсвэл холимог (RC) хуваагч юм. Эсэргүүцлийн хуваагчийн хувиргалтын коэффициент:"}, {"t": "eq", "s": "K R=(R 1+R 2)/R 2, K C=(C 1+C 2)/C 1 (5.21)", "h": "K<sub>R</sub>=(R<sub>1</sub>+R<sub>2</sub>)/R<sub>2</sub>, K<sub>C</sub>=(C<sub>1</sub>+C<sub>2</sub>)/C<sub>1</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>K</mi><mi>R</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>R</mi><mn>1</mn></msub><mo>+</mo><msub><mi>R</mi><mn>2</mn></msub></mrow><msub><mi>R</mi><mn>2</mn></msub></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>K</mi><mi>C</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>C</mi><mn>1</mn></msub><mo>+</mo><msub><mi>C</mi><mn>2</mn></msub></mrow><msub><mi>C</mi><mn>1</mn></msub></mfrac></mrow></semantics></math>", "n": "5.21"}, {"t": "p", "s": "Жишээлбэл 10 кВ-ын сүлжээнд гаралт 3.25/√(3) В байх хуваагчийн коэффициент K R=10000/3.25=3077; R 1=100 МОм бол R 2=R 1/(K R−1)=32.5 кОм болно. R хуваагч сарнилын багтаамжаас болж өндөр давтамжид алдаатай, C хуваагч тогтмол гүйдэлд ажиллахгүй. Иймээс RC хуваагч нь хоёрын давуу талыг хослуулж, R 1C 1=R 2C 2 нөхцөлөөр давтамжаас хамааралгүй хуваалт өгнө. Хуваагч нь феррорезонансгүй, шугаман, бага жинтэй тул 6–35 кВ-ын битүү хуваарилах байгууламжийн нүдэнд (КРУ) тулгуур тусгаарлагч эсвэл кабелийн залгуурт шингээж суурилуулдаг.", "h": "Жишээлбэл 10 кВ-ын сүлжээнд гаралт 3.25/√(3) В байх хуваагчийн коэффициент K<sub>R</sub>=10000/3.25=3077; R<sub>1</sub>=100 МОм бол R<sub>2</sub>=R<sub>1</sub>/(K<sub>R</sub>−1)=32.5 кОм болно. R хуваагч сарнилын багтаамжаас болж өндөр давтамжид алдаатай, C хуваагч тогтмол гүйдэлд ажиллахгүй. Иймээс RC хуваагч нь хоёрын давуу талыг хослуулж, R<sub>1</sub>C<sub>1</sub>=R<sub>2</sub>C<sub>2</sub> нөхцөлөөр давтамжаас хамааралгүй хуваалт өгнө. Хуваагч нь феррорезонансгүй, шугаман, бага жинтэй тул 6–35 кВ-ын битүү хуваарилах байгууламжийн нүдэнд (КРУ) тулгуур тусгаарлагч эсвэл кабелийн залгуурт шингээж суурилуулдаг."}, {"t": "h", "l": 2, "s": "4.4. LPIT-ийн\nстандартчилал (IEC 61869-6, -10, -11)", "h": "4.4. LPIT-ийн\nстандартчилал (IEC 61869-6, -10, -11)"}, {"t": "p", "s": "IEC 61869-6 нь бага чадлын хэмжүүрийн трансформаторын ерөнхий шаардлагыг, -10 нь идэвхгүй бага чадлын ГТ-ийг (LPCT: Роговскийн ороомог, бага чадлын төмөр цөмт ГТ шунттай), -11 нь идэвхгүй LPVT-ийг тодорхойлно. Аналог гаралтын нэрлэсэн утгуудаас Роговскийн ороомогт 22.5 мВ, 150 мВ, 225 мВ (нэрлэсэн гүйдэл ба давтамжид), LPVT-д 3.25/√(3) В зэрэг утгууд хэрэглэгддэг. Нарийвчлалын анги уламжлалтынхтай ижил (0.1–1, 5P, 10P), харин хамгаалалтын анги нь өргөтгөсөн динамик хүрээ, давтамжийн шаардлагатай. Хүснэгт 5.5-д уламжлалт ба уламжлалт бус мэдрэгчийг харьцуулав.", "h": "IEC 61869-6 нь бага чадлын хэмжүүрийн трансформаторын ерөнхий шаардлагыг, -10 нь идэвхгүй бага чадлын ГТ-ийг (LPCT: Роговскийн ороомог, бага чадлын төмөр цөмт ГТ шунттай), -11 нь идэвхгүй LPVT-ийг тодорхойлно. Аналог гаралтын нэрлэсэн утгуудаас Роговскийн ороомогт 22.5 мВ, 150 мВ, 225 мВ (нэрлэсэн гүйдэл ба давтамжид), LPVT-д 3.25/√(3) В зэрэг утгууд хэрэглэгддэг. Нарийвчлалын анги уламжлалтынхтай ижил (0.1–1, 5P, 10P), харин хамгаалалтын анги нь өргөтгөсөн динамик хүрээ, давтамжийн шаардлагатай. Хүснэгт 5.5-д уламжлалт ба уламжлалт бус мэдрэгчийг харьцуулав."}, {"t": "cap", "s": "Хүснэгт 5.5. Хэмжүүрийн мэдрэгчийн технологийн харьцуулалт", "h": "Хүснэгт 5.5. Хэмжүүрийн мэдрэгчийн технологийн харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Үзүүлэлт", "Цөмтэй ГТ", "Оптик ГТ", "Роговский", "Индуктив ХТ / CVT", "RC хуваагч"], "rows": [["Ханалт", "Бий", "Байхгүй", "Байхгүй", "Бий / —", "Байхгүй"], ["Динамик хүрээ", "1–20 (50) I<sub>н</sub>", "0.01–100 I<sub>н</sub>", "0.01–200 I<sub>н</sub>", "0.05–1.9 U<sub>н</sub>", "0.01–2 U<sub>н</sub>"], ["Давтамжийн зурвас", "≈ 5 кГц хүртэл", "DC–5 кГц", "0.1 Гц–1 МГц", "≈ 1 кГц / нарийн", "DC–100 кГц+"], ["Тогтмол гүйдэл", "Үгүй", "Тийм", "Интеграторын тусламжтай", "Үгүй", "Тийм (R, RC)"], ["Феррорезонанс", "—", "—", "—", "Эрсдэлтэй", "Байхгүй"], ["Гаралт", "1/5 А", "Дижитал", "мВ / дижитал", "100 В", "В / дижитал"], ["Жин (110 кВ)", "400–800 кг", "50–150 кг", "Хэдэн кг (мэдрэгч)", "300–600 кг", "—"], ["Хоёрдогч задралын аюул", "Өндөр", "Үгүй", "Үгүй", "Богино холболтын аюул", "Үгүй"]]}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.8. Мэдрэгчийн шугаман байдал ба давтамжийн зурвасын харьцуулалт (чанарын дүрслэл)", "h": "Зураг 5.8. Мэдрэгчийн шугаман байдал ба давтамжийн зурвасын харьцуулалт (чанарын дүрслэл)"}, {"t": "p", "s": "Зураг 5.8, а-аас харахад цөмтэй ГТ бага гүйдэлд соронзлох гүйдлээс, их гүйдэлд ханалтаас болж алдаа өсдөг бол Роговскийн ба оптик ГТ-ийн алдаа өргөн хүрээнд тогтмол байна. Иймээс нэг LPIT мэдрэгч хэмжүүрийн ба хамгаалалтын хоёр цөмийг орлож чадна.", "h": "Зураг 5.8, а-аас харахад цөмтэй ГТ бага гүйдэлд соронзлох гүйдлээс, их гүйдэлд ханалтаас болж алдаа өсдөг бол Роговскийн ба оптик ГТ-ийн алдаа өргөн хүрээнд тогтмол байна. Иймээс нэг LPIT мэдрэгч хэмжүүрийн ба хамгаалалтын хоёр цөмийг орлож чадна."}, {"t": "h", "l": 1, "s": "5. Нэгтгэх төхөөрөмж ба\nпроцессын түвшин", "h": "5. Нэгтгэх төхөөрөмж ба\nпроцессын түвшин"}, {"t": "h", "l": 2, "s": "5.1. Нэгтгэх төхөөрөмжийн бүтэц", "h": "5.1. Нэгтгэх төхөөрөмжийн бүтэц"}, {"t": "p", "s": "Нэгтгэх төхөөрөмж (Merging Unit, MU) нь гурван фазын гүйдэл, хүчдэлийн (ихэвчлэн 4I + 4U) аналог дохиог синхрон түүвэрлэж, дижитал хэлбэрт шилжүүлэн, IEC 61850-9-2 / IEC 61869-9-ийн түүвэрлэлтийн утгын (Sampled Values, SV) багц болгон процессын шина руу дамжуулна (Зураг 5.9). MU-ийн гол хэсгүүд нь: оролтын хувиргагч ба галваник тусгаарлалт, Найквистийн давтамжаас дээших бүрэлдэхүүнийг дарах anti-aliasing шүүлтүүр, АЦХ (16–24 бит, ΣΔ эсвэл SAR), DSP/FPGA (Роговскийн дохиог интегралчлах, мэдрэгчийн алдааг калибровкын коэффициентоор залруулах, дахин түүвэрлэх), цагийн синхрончлол, Ethernet интерфейс. Мөн MU-д таслуур, салгуурын төлөв, тушаалыг GOOSE мессежээр дамжуулах оролт/гаралт нэгтгэгдэж болно.", "h": "<b>Нэгтгэх төхөөрөмж</b> (Merging Unit, MU) нь гурван фазын гүйдэл, хүчдэлийн (ихэвчлэн 4I + 4U) аналог дохиог синхрон түүвэрлэж, дижитал хэлбэрт шилжүүлэн, IEC 61850-9-2 / IEC 61869-9-ийн түүвэрлэлтийн утгын (Sampled Values, SV) багц болгон процессын шина руу дамжуулна (Зураг 5.9). MU-ийн гол хэсгүүд нь: оролтын хувиргагч ба галваник тусгаарлалт, Найквистийн давтамжаас дээших бүрэлдэхүүнийг дарах anti-aliasing шүүлтүүр, АЦХ (16–24 бит, ΣΔ эсвэл SAR), DSP/FPGA (Роговскийн дохиог интегралчлах, мэдрэгчийн алдааг калибровкын коэффициентоор залруулах, дахин түүвэрлэх), цагийн синхрончлол, Ethernet интерфейс. Мөн MU-д таслуур, салгуурын төлөв, тушаалыг GOOSE мессежээр дамжуулах оролт/гаралт нэгтгэгдэж болно."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.9. Нэгтгэх төхөөрөмжийн (MU) бүтцийн схем", "h": "Зураг 5.9. Нэгтгэх төхөөрөмжийн (MU) бүтцийн схем"}, {"t": "p", "s": "MU-ийг мэдрэгчтэй хамт нэг үйлдвэрлэгч нийлүүлдэг (оптик ГТ, LPIT-д) эсвэл уламжлалт ГТ, ХТ-ийн 1/5 А, 100 В-ын гаралтад холбогддог бие даасан нэгтгэх төхөөрөмж (Stand-Alone Merging Unit, SAMU, IEC 61869-13) хэлбэртэй байна. SAMU нь одоо ашиглагдаж буй дэд станцын анхдагч тоноглолыг солихгүйгээр процессын шинад шилжих («retrofit») гол хэрэгсэл бөгөөд ихэвчлэн тоноглолын дэргэдэх ил талбайн шүүгээнд суурилагддаг тул −40…+70 °C-д ажиллах, цахилгаан соронзон нийцлийн өндөр шаардлагыг хангах ёстой.", "h": "MU-ийг мэдрэгчтэй хамт нэг үйлдвэрлэгч нийлүүлдэг (оптик ГТ, LPIT-д) эсвэл уламжлалт ГТ, ХТ-ийн 1/5 А, 100 В-ын гаралтад холбогддог <b>бие даасан нэгтгэх төхөөрөмж</b> (Stand-Alone Merging Unit, SAMU, IEC 61869-13) хэлбэртэй байна. SAMU нь одоо ашиглагдаж буй дэд станцын анхдагч тоноглолыг солихгүйгээр процессын шинад шилжих («retrofit») гол хэрэгсэл бөгөөд ихэвчлэн тоноглолын дэргэдэх ил талбайн шүүгээнд суурилагддаг тул −40…+70 °C-д ажиллах, цахилгаан соронзон нийцлийн өндөр шаардлагыг хангах ёстой."}, {"t": "h", "l": 2, "s": "5.2. IEC 61869-9\nтүүвэрлэлт ба дижитал гаралт", "h": "5.2. IEC 61869-9\nтүүвэрлэлт ба дижитал гаралт"}, {"t": "p", "s": "IEC 61850-9-2-ын анхны хэрэглээний профайл «9-2LE» нь 50 Гц-ийн системд үед 80 түүвэр (4000 Гц, нэг багцад 1 ASDU) ба эрчим хүчний чанарт 256 түүвэр/үе хэрэглэдэг байв. IEC 61869-9 нь давтамжаас хамааралгүй санал болгосон түүвэрлэлтийн давтамж-ийг тогтоосон (Хүснэгт 5.6). Нэг үеийн түүврийн тоо ба хэмжих хамгийн их гармоник:", "h": "IEC 61850-9-2-ын анхны хэрэглээний профайл «9-2LE» нь 50 Гц-ийн системд үед 80 түүвэр (4000 Гц, нэг багцад 1 ASDU) ба эрчим хүчний чанарт 256 түүвэр/үе хэрэглэдэг байв. IEC 61869-9 нь давтамжаас хамааралгүй <b>санал болгосон түүвэрлэлтийн давтамж</b>-ийг тогтоосон (Хүснэгт 5.6). Нэг үеийн түүврийн тоо ба хэмжих хамгийн их гармоник:"}, {"t": "eq", "s": "N үе=f s/f, n max<f s/2f (5.22)", "h": "N<sub>үе</sub>=f<sub>s</sub>/f, n<sub>max</sub>&lt;f<sub>s</sub>/2f", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mrow><mi>ү</mi><mi>е</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>f</mi><mi>s</mi></msub><mi>f</mi></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>n</mi><mrow><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>&lt;</mo><mfrac><msub><mi>f</mi><mi>s</mi></msub><mrow><mn>2</mn><mi>f</mi></mrow></mfrac></mrow></semantics></math>", "n": "5.22"}, {"t": "p", "s": "энд f s — түүвэрлэлтийн давтамж, f — сүлжээний давтамж. 4800 Гц-д 50 Гц-ийн системд нэг үед 96 түүвэр, онолын хамгийн их гармоник 47 (практикт anti-aliasing шүүлтүүрийн улмаас 20–30); 14 400 Гц-д 288 түүвэр, 143-р гармоник хүртэл хэмжих боломжтой.", "h": "энд f<sub>s</sub> — түүвэрлэлтийн давтамж, f — сүлжээний давтамж. 4800 Гц-д 50 Гц-ийн системд нэг үед 96 түүвэр, онолын хамгийн их гармоник 47 (практикт anti-aliasing шүүлтүүрийн улмаас 20–30); 14 400 Гц-д 288 түүвэр, 143-р гармоник хүртэл хэмжих боломжтой."}, {"t": "cap", "s": "Хүснэгт 5.6. IEC 61869-9 ба 9-2LE-ийн дижитал гаралтын үндсэн параметр", "h": "Хүснэгт 5.6. IEC 61869-9 ба 9-2LE-ийн дижитал гаралтын үндсэн параметр"}, {"t": "tbl", "s": "", "head": ["Параметр", "9-2LE (хамгаалалт)", "IEC 61869-9: хамгаалалт, хэмжилт", "IEC 61869-9: эрчим хүчний чанар", "IEC 61869-9: тогтмол гүйдэл"], "rows": [["Түүвэрлэлтийн давтамж", "4000 Гц (50 Гц-д)", "4800 Гц", "14 400 Гц", "96 000 Гц"], ["Нэг багц дахь ASDU", "1", "2", "6", "1"], ["Багцын давтамж, 1/с", "4000", "2400", "2400", "96 000"], ["Өгөгдлийн сувгууд", "4I + 4U", "4I + 4U (тохируулж болно)", "4I + 4U", "Тохируулна"], ["Утгын формат", "32 бит бүхэл + 32 бит чанар", "Мөн адил", "Мөн адил", "Мөн адил"], ["Синхрончлол", "1PPS", "PTP (IEC 61850-9-3)", "PTP", "PTP"]]}, {"t": "p", "s": "Багц бүр дахь ASDU (Application Service Data Unit) нь урсгалын нэр (svID), түүврийн дугаар (smpCnt, секунд бүр 0-ээс эхэлж дахин тоологдоно), тохиргооны хувилбар (confRev), синхрончлолын төлөв (smpSynch), сувгийн утга ба чанарын битүүдийг агуулна. Чанарын бит нь хүлээн авагч IED-д тухайн түүвэр хүчинтэй эсэх, синхрончлол алдагдсан, тест горимд байгаа эсэхийг мэдээлж, хамгаалалтын алгоритмыг блоклох эсэхийг шийднэ.", "h": "Багц бүр дахь ASDU (Application Service Data Unit) нь урсгалын нэр (svID), түүврийн дугаар (smpCnt, секунд бүр 0-ээс эхэлж дахин тоологдоно), тохиргооны хувилбар (confRev), синхрончлолын төлөв (smpSynch), сувгийн утга ба чанарын битүүдийг агуулна. Чанарын бит нь хүлээн авагч IED-д тухайн түүвэр хүчинтэй эсэх, синхрончлол алдагдсан, тест горимд байгаа эсэхийг мэдээлж, хамгаалалтын алгоритмыг блоклох эсэхийг шийднэ."}, {"t": "h", "l": 2, "s": "5.3. Цагийн синхрончлол ба\nхоцрогдол", "h": "5.3. Цагийн синхрончлол ба\nхоцрогдол"}, {"t": "p", "s": "Өөр өөр MU-ээс ирсэн түүврийг (жишээ нь дифференциал хамгаалалтад шугамын хоёр тал, трансформаторын гурван тал) харьцуулахын тулд бүх MU нэг цагийн эх үүсвэрт синхрон түүвэрлэх ёстой. Цагийн алдаа Δt нь фазын алдаа үүсгэнэ:", "h": "Өөр өөр MU-ээс ирсэн түүврийг (жишээ нь дифференциал хамгаалалтад шугамын хоёр тал, трансформаторын гурван тал) харьцуулахын тулд бүх MU нэг цагийн эх үүсвэрт синхрон түүвэрлэх ёстой. Цагийн алдаа Δt нь фазын алдаа үүсгэнэ:"}, {"t": "eq", "s": "Δφ=360^∘⋅f⋅Δt (5.23)", "h": "Δφ=360<sup>∘</sup>⋅f⋅Δt", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>φ</mi><mo>=</mo><msup><mn>360</mn><mo>∘</mo></msup><mo>⋅</mo><mi>f</mi><mo>⋅</mo><mi>Δ</mi><mi>t</mi></mrow></semantics></math>", "n": "5.23"}, {"t": "p", "s": "50 Гц-д 1 мкс-ийн алдаа 0.018^∘=1.08′, 10 мкс нь 10.8′-ийн фазын алдаа өгнө. 0.2 ангийн фазын шилжилтийн хязгаар 10′ тул тоолуурын хэрэглээнд синхрончлолын алдаа 1 мкс-ийн түвшинд байх шаардлагатай. Иймээс дижитал дэд станцад IEC 61850-9-3 (эрчим хүчний профайлтай PTP, IEEE 1588) хэрэглэж, GPS/GNSS-д суурилсан гранд-мастер цаг, хоёрдмол хувилбар, «holdover» горимыг (GPS алдагдсан үед дотоод генератороор цагийг хадгалах) заавал төлөвлөнө. Дэд станц доторх хамгаалалт (шинын, трансформаторын дифференциал) нь гадаад цаг алдагдсан ч ажиллах ёстой тул орон нутгийн синхрончлолыг (smpSynch = local) хүлээн зөвшөөрөх тохиргоог хийнэ.", "h": "50 Гц-д 1 мкс-ийн алдаа 0.018<sup>∘</sup>=1.08′, 10 мкс нь 10.8′-ийн фазын алдаа өгнө. 0.2 ангийн фазын шилжилтийн хязгаар 10′ тул тоолуурын хэрэглээнд синхрончлолын алдаа 1 мкс-ийн түвшинд байх шаардлагатай. Иймээс дижитал дэд станцад IEC 61850-9-3 (эрчим хүчний профайлтай PTP, IEEE 1588) хэрэглэж, GPS/GNSS-д суурилсан гранд-мастер цаг, хоёрдмол хувилбар, «holdover» горимыг (GPS алдагдсан үед дотоод генератороор цагийг хадгалах) заавал төлөвлөнө. Дэд станц доторх хамгаалалт (шинын, трансформаторын дифференциал) нь гадаад цаг алдагдсан ч ажиллах ёстой тул орон нутгийн синхрончлолыг (smpSynch = local) хүлээн зөвшөөрөх тохиргоог хийнэ."}, {"t": "p", "s": "Хамгаалалтын нийт ажиллах хугацаанд дижитал хэмжилтийн хэлхээ нэмэлт хоцрогдол оруулна:", "h": "Хамгаалалтын нийт ажиллах хугацаанд дижитал хэмжилтийн хэлхээ нэмэлт хоцрогдол оруулна:"}, {"t": "eq", "s": "t нийт=t MU+∑ k=1^m(8L/B+t sw)+t IED+t GOOSE+t таслуур (5.24)", "h": "t<sub>нийт</sub>=t<sub>MU</sub>+∑<sub>k=1</sub><sup>m</sup>(8L/B+t<sub>sw</sub>)+t<sub>IED</sub>+t<sub>GOOSE</sub>+t<sub>таслуур</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mrow><mi>н</mi><mi>и</mi><mi>й</mi><mi>т</mi></mrow></msub><mo>=</mo><msub><mi>t</mi><mrow><mi>M</mi><mi>U</mi></mrow></msub><mo>+</mo><munderover><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>m</mi></munderover><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mfrac><mrow><mn>8</mn><mi>L</mi></mrow><mi>B</mi></mfrac><mo>+</mo><msub><mi>t</mi><mrow><mi>s</mi><mi>w</mi></mrow></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>+</mo><msub><mi>t</mi><mrow><mi>I</mi><mi>E</mi><mi>D</mi></mrow></msub><mo>+</mo><msub><mi>t</mi><mrow><mi>G</mi><mi>O</mi><mi>O</mi><mi>S</mi><mi>E</mi></mrow></msub><mo>+</mo><msub><mi>t</mi><mrow><mi>т</mi><mi>а</mi><mi>с</mi><mi>л</mi><mi>у</mi><mi>у</mi><mi>р</mi></mrow></msub></mrow></semantics></math>", "n": "5.24"}, {"t": "p", "s": "энд t MU — MU-ийн түүвэрлэлт, шүүлт, багц үүсгэх хоцрогдол (IEC 61869-9 хамгаалалтын хэрэглээнд 2 мс-ээс хэтрэхгүй байхыг шаарддаг, бодит MU-д 0.5–1 мс); L — багцын урт, байт; B — сүлжээний хурд, бит/с; t sw — свичийн дотоод хоцрогдол; m — свичийн тоо.", "h": "энд t<sub>MU</sub> — MU-ийн түүвэрлэлт, шүүлт, багц үүсгэх хоцрогдол (IEC 61869-9 хамгаалалтын хэрэглээнд 2 мс-ээс хэтрэхгүй байхыг шаарддаг, бодит MU-д 0.5–1 мс); L — багцын урт, байт; B — сүлжээний хурд, бит/с; t<sub>sw</sub> — свичийн дотоод хоцрогдол; m — свичийн тоо."}, {"t": "h", "l": 2, "s": "5.4. Нарийвчлалын төсөв", "h": "5.4. Нарийвчлалын төсөв"}, {"t": "p", "s": "Дижитал хэмжилтийн гинжин хэлхээний нийт алдаа нь мэдрэгч, MU-ийн АЦХ ба боловсруулалт, цагийн синхрончлол, дахин түүвэрлэлтийн алдаануудаас бүрдэнэ. Хамааралгүй санамсаргүй бүрэлдэхүүнүүдийн хувьд квадрат нийлбэрийн язгуураар (RSS), хамгийн муу тохиолдолд арифметик нийлбэрээр үнэлнэ:", "h": "Дижитал хэмжилтийн гинжин хэлхээний нийт алдаа нь мэдрэгч, MU-ийн АЦХ ба боловсруулалт, цагийн синхрончлол, дахин түүвэрлэлтийн алдаануудаас бүрдэнэ. Хамааралгүй санамсаргүй бүрэлдэхүүнүүдийн хувьд квадрат нийлбэрийн язгуураар (RSS), хамгийн муу тохиолдолд арифметик нийлбэрээр үнэлнэ:"}, {"t": "eq", "s": "ε Σ=√(∑ jε j^2), ε Σ,max=∑ j|ε j| (5.25)", "h": "ε<sub>Σ</sub>=√(∑<sub>j</sub>ε<sub>j</sub><sup>2</sup>), ε<sub>Σ,max</sub>=∑<sub>j</sub>|ε<sub>j</sub>|", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε</mi><mi>Σ</mi></msub><mo>=</mo><msqrt><mrow><munder><mo>∑</mo><mi>j</mi></munder><msubsup><mi>ε</mi><mi>j</mi><mn>2</mn></msubsup></mrow></msqrt><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>ε</mi><mrow><mi>Σ</mi><mo>,</mo><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><mrow><mo form=\"prefix\" stretchy=\"true\">|</mo><msub><mi>ε</mi><mi>j</mi></msub><mo form=\"postfix\" stretchy=\"true\">|</mo></mrow></mrow></semantics></math>", "n": "5.25"}, {"t": "p", "s": "IEC 61869-6, -9-өөр LPIT ба MU-г хамтад нь (мэдрэгчийн оролтоос дижитал гаралт хүртэл) нарийвчлалын ангид баталгаажуулдаг. Харин SAMU-г уламжлалт ГТ-тэй хослуулбал ГТ ба SAMU-ийн алдаа нэмэгдэх тул тоолуурын хэрэглээнд хамгийн муу нийлбэрээр шалгах шаардлагатай.", "h": "IEC 61869-6, -9-өөр LPIT ба MU-г <b>хамтад нь</b> (мэдрэгчийн оролтоос дижитал гаралт хүртэл) нарийвчлалын ангид баталгаажуулдаг. Харин SAMU-г уламжлалт ГТ-тэй хослуулбал ГТ ба SAMU-ийн алдаа нэмэгдэх тул тоолуурын хэрэглээнд хамгийн муу нийлбэрээр шалгах шаардлагатай."}, {"t": "p", "s": "Жишээ 5.7. 110 кВ-ын арилжааны тоолуурын хэмжилтийн гинжин хэлхээг 0.2 ангид шалгая. Алдааны бүрэлдэхүүн (нэрлэсэн гүйдэлд): LPCT мэдрэгч 0.10 %, 3′; MU-ийн АЦХ ба шүүлтүүр 0.05 %, 2′; температурын шилжилт 0.02 %; дахин түүвэрлэлт 0.05 %, 2′; PTP синхрончлолын алдаа 1 мкс.", "h": "<b>Жишээ 5.7.</b> 110 кВ-ын арилжааны тоолуурын хэмжилтийн гинжин хэлхээг 0.2 ангид шалгая. Алдааны бүрэлдэхүүн (нэрлэсэн гүйдэлд): LPCT мэдрэгч 0.10 %, 3′; MU-ийн АЦХ ба шүүлтүүр 0.05 %, 2′; температурын шилжилт 0.02 %; дахин түүвэрлэлт 0.05 %, 2′; PTP синхрончлолын алдаа 1 мкс.", "x": "ex"}, {"t": "p", "s": "Бодолт. (5.23)-аар синхрончлолын фазын алдаа 360⋅50⋅10^−6=0.018^∘=1.08′. (5.25)-аар харьцааны алдаа: RSS √(0.10^2+0.05^2+0.02^2+0.05^2)=0.124 %, хамгийн муу 0.10+0.05+0.02+0.05=0.22 %. Фазын алдаа: RSS √(3^2+2^2+1.08^2+2^2)=4.26′, хамгийн муу 8.08′. Дүгнэлт (Хүснэгт 5.7): фазын алдаа хоёр аргаар 10′-ийн хязгаарт багтана; харьцааны алдаа RSS-ээр (0.124 %) хангагдах ч хамгийн муу нийлбэрээр (0.22 %) 0.2 %-ийн хязгаарыг давна. Иймээс мэдрэгч + MU-г хамтад нь баталгаажуулсан (туршилтын протоколтой) шийдэл сонгох, эсвэл 0.1 ангийн мэдрэгч хэрэглэх нь зүйтэй. Синхрончлолын алдаа 10 мкс болбол дангаараа 10.8′ болж хязгаарыг давна.", "h": "<i>Бодолт.</i> (5.23)-аар синхрончлолын фазын алдаа 360⋅50⋅10<sup>−6</sup>=0.018<sup>∘</sup>=1.08′. (5.25)-аар харьцааны алдаа: RSS √(0.10<sup>2</sup>+0.05<sup>2</sup>+0.02<sup>2</sup>+0.05<sup>2</sup>)=0.124 %, хамгийн муу 0.10+0.05+0.02+0.05=0.22 %. Фазын алдаа: RSS √(3<sup>2</sup>+2<sup>2</sup>+1.08<sup>2</sup>+2<sup>2</sup>)=4.26′, хамгийн муу 8.08′. Дүгнэлт (Хүснэгт 5.7): фазын алдаа хоёр аргаар 10′-ийн хязгаарт багтана; харьцааны алдаа RSS-ээр (0.124 %) хангагдах ч хамгийн муу нийлбэрээр (0.22 %) 0.2 %-ийн хязгаарыг давна. Иймээс мэдрэгч + MU-г хамтад нь баталгаажуулсан (туршилтын протоколтой) шийдэл сонгох, эсвэл 0.1 ангийн мэдрэгч хэрэглэх нь зүйтэй. Синхрончлолын алдаа 10 мкс болбол дангаараа 10.8′ болж хязгаарыг давна.", "x": "ex"}, {"t": "cap", "s": "Хүснэгт 5.7. Жишээ 5.7-ын нарийвчлалын төсөв", "h": "Хүснэгт 5.7. Жишээ 5.7-ын нарийвчлалын төсөв"}, {"t": "tbl", "s": "", "head": ["Бүрэлдэхүүн", "Харьцааны алдаа, %", "Фазын алдаа, мин"], "rows": [["LPCT мэдрэгч", "0.10", "3.0"], ["MU: АЦХ, anti-aliasing шүүлтүүр", "0.05", "2.0"], ["Температурын шилжилт", "0.02", "—"], ["Дахин түүвэрлэлт", "0.05", "2.0"], ["Синхрончлол (1 мкс)", "—", "1.08"], ["Нийт RSS / хамгийн муу", "0.124 / 0.22", "4.26 / 8.08"], ["0.2 ангийн хязгаар", "0.2", "10"]]}, {"t": "h", "l": 2, "s": "5.5. Процессын шина", "h": "5.5. Процессын шина"}, {"t": "p", "s": "Процессын шина нь процессын түвшний тоноглол (MU, таслуурын IED) ба бэйн түвшний хамгаалалт, удирдлагын IED-ийг холбосон Ethernet сүлжээ юм (Зураг 5.10). Уламжлалт дэд станцад ГТ, ХТ-ийн хоёрдогч хэлхээ, таслуурын удирдлага, дохиоллын олон зуун зэс судал маршрутын шүүгээгээр дамжин релений өрөөнд ирдэг бол процессын шинатай дэд станцад эдгээрийг хэдэн оптик кабель орлоно.", "h": "<b>Процессын шина</b> нь процессын түвшний тоноглол (MU, таслуурын IED) ба бэйн түвшний хамгаалалт, удирдлагын IED-ийг холбосон Ethernet сүлжээ юм (Зураг 5.10). Уламжлалт дэд станцад ГТ, ХТ-ийн хоёрдогч хэлхээ, таслуурын удирдлага, дохиоллын олон зуун зэс судал маршрутын шүүгээгээр дамжин релений өрөөнд ирдэг бол процессын шинатай дэд станцад эдгээрийг хэдэн оптик кабель орлоно."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 5.10. Уламжлалт ба процессын шинатай дэд станцын хоёрдогч хэлхээний харьцуулалт", "h": "Зураг 5.10. Уламжлалт ба процессын шинатай дэд станцын хоёрдогч хэлхээний харьцуулалт"}, {"t": "p", "s": "SV урсгалын зурвасын өргөн:", "h": "SV урсгалын зурвасын өргөн:"}, {"t": "eq", "s": "B SV=8 L багц f багц (5.26)", "h": "B<sub>SV</sub>=8 L<sub>багц</sub> f<sub>багц</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mrow><mi>S</mi><mi>V</mi></mrow></msub><mo>=</mo><mn>8</mn><mspace width=\"0.167em\"></mspace><msub><mi>L</mi><mrow><mi>б</mi><mi>а</mi><mi>г</mi><mi>ц</mi></mrow></msub><mspace width=\"0.167em\"></mspace><msub><mi>f</mi><mrow><mi>б</mi><mi>а</mi><mi>г</mi><mi>ц</mi></mrow></msub></mrow></semantics></math>", "n": "5.26"}, {"t": "p", "s": "энд L багц — Ethernet багцын нийт урт (преамбул, багц хоорондын завсрыг оруулсан), байт; f багц — секундэд илгээх багцын тоо. SV нь multicast мессеж тул VLAN, свичийн multicast шүүлтээр урсгалыг зөвхөн шаардлагатай портод хүргэнэ.", "h": "энд L<sub>багц</sub> — Ethernet багцын нийт урт (преамбул, багц хоорондын завсрыг оруулсан), байт; f<sub>багц</sub> — секундэд илгээх багцын тоо. SV нь multicast мессеж тул VLAN, свичийн multicast шүүлтээр урсгалыг зөвхөн шаардлагатай портод хүргэнэ."}, {"t": "p", "s": "Жишээ 5.8. IEC 61869-9-ийн 4800 Гц-ийн профайлтай (нэг багцад 2 ASDU, 8 суваг) SV урсгалын зурвасын өргөн, 100 Мбит/с-ийн процессын шинад (ачааллыг 60 %-иас хэтрүүлэхгүй) холбох MU-ийн тоо, гурван свичээр дамжих сүлжээний хоцрогдлыг тооцъё. Нэг ASDU ≈ 93 байт (svID 12, smpCnt 4, confRev 6, smpSynch 3, 8 суваг × 8 байт + толгой 2 + тэмдэг 2), SV ба APDU толгой 17 байт, Ethernet толгой, VLAN, FCS 22 байт, преамбул ба завсар 20 байт; свичийн дотоод хоцрогдол 5 мкс.", "h": "<b>Жишээ 5.8.</b> IEC 61869-9-ийн 4800 Гц-ийн профайлтай (нэг багцад 2 ASDU, 8 суваг) SV урсгалын зурвасын өргөн, 100 Мбит/с-ийн процессын шинад (ачааллыг 60 %-иас хэтрүүлэхгүй) холбох MU-ийн тоо, гурван свичээр дамжих сүлжээний хоцрогдлыг тооцъё. Нэг ASDU ≈ 93 байт (svID 12, smpCnt 4, confRev 6, smpSynch 3, 8 суваг × 8 байт + толгой 2 + тэмдэг 2), SV ба APDU толгой 17 байт, Ethernet толгой, VLAN, FCS 22 байт, преамбул ба завсар 20 байт; свичийн дотоод хоцрогдол 5 мкс.", "x": "ex"}, {"t": "p", "s": "Бодолт. L багц=17+2⋅93+22+20=245 байт. (5.26)-аар B SV=8⋅245⋅2400=4.70 Мбит/с. Харьцуулахад 9-2LE (1 ASDU, 4000 багц/с): L=152 байт, B=4.86 Мбит/с; эрчим хүчний чанарын 14 400 Гц-ийн профайл (6 ASDU): L=617 байт, B=11.85 Мбит/с. MU-ийн тоо: 0.6⋅100/4.70=12.8 ⇒ 12 MU. Нэг багцыг 100 Мбит/с-д дамжуулах хугацаа 8⋅245/10^8=19.6 мкс; (5.24)-өөр гурван свичээр (store-and-forward) 3⋅(19.6+5)=73.8 мкс. MU-ийн хоцрогдол 1 мс-тэй нийлбэл SV хэмжилтийн хоцрогдол ≈ 1.07 мс бөгөөд хамгаалалтын 15–25 мс-ийн ажиллах хугацаатай харьцуулахад бага ч уламжлалт аналог оролттой хамгаалалтаас 1 мс орчим удаан. Шинын хамгаалалт олон бэйн урсгалыг нэгэн зэрэг хүлээн авдаг тул 1 Гбит/с-ийн свич хэрэглэнэ.", "h": "<i>Бодолт.</i> L<sub>багц</sub>=17+2⋅93+22+20=245 байт. (5.26)-аар B<sub>SV</sub>=8⋅245⋅2400=4.70 Мбит/с. Харьцуулахад 9-2LE (1 ASDU, 4000 багц/с): L=152 байт, B=4.86 Мбит/с; эрчим хүчний чанарын 14 400 Гц-ийн профайл (6 ASDU): L=617 байт, B=11.85 Мбит/с. MU-ийн тоо: 0.6⋅100/4.70=12.8 ⇒ 12 MU. Нэг багцыг 100 Мбит/с-д дамжуулах хугацаа 8⋅245/10<sup>8</sup>=19.6 мкс; (5.24)-өөр гурван свичээр (store-and-forward) 3⋅(19.6+5)=73.8 мкс. MU-ийн хоцрогдол 1 мс-тэй нийлбэл SV хэмжилтийн хоцрогдол ≈ 1.07 мс бөгөөд хамгаалалтын 15–25 мс-ийн ажиллах хугацаатай харьцуулахад бага ч уламжлалт аналог оролттой хамгаалалтаас 1 мс орчим удаан. Шинын хамгаалалт олон бэйн урсгалыг нэгэн зэрэг хүлээн авдаг тул 1 Гбит/с-ийн свич хэрэглэнэ.", "x": "ex"}, {"t": "p", "s": "Процессын шинын найдвартай ажиллагааг IEC 62439-3-ийн PRP (Parallel Redundancy Protocol, хоёр бие даасан сүлжээгээр давхар илгээх) эсвэл HSR (High-availability Seamless Redundancy, цагираг) протоколоор хангаж, нэг холбоос тасрахад ч тэг хугацааны сэргэлттэй байлгана (Лекц 6).", "h": "Процессын шинын найдвартай ажиллагааг IEC 62439-3-ийн PRP (Parallel Redundancy Protocol, хоёр бие даасан сүлжээгээр давхар илгээх) эсвэл HSR (High-availability Seamless Redundancy, цагираг) протоколоор хангаж, нэг холбоос тасрахад ч тэг хугацааны сэргэлттэй байлгана (Лекц 6)."}, {"t": "h", "l": 1, "s": "6.\nДижитал дэд станцад үзүүлэх давуу тал ба Монголын практик", "h": "6.\nДижитал дэд станцад үзүүлэх давуу тал ба Монголын практик"}, {"t": "h", "l": 2, "s": "6.1. Давуу тал ба сорилт", "h": "6.1. Давуу тал ба сорилт"}, {"t": "p", "s": "Шинэ хэмжүүрийн технологи ба процессын шинын нэгдэл нь дэд станцын хоёрдогч системд чанарын өөрчлөлт авчирна (Хүснэгт 5.8). Хамгийн чухал нь аюулгүй байдал: ГТ-ийн хоёрдогч хэлхээг задлахад мянга мянган вольтын хүчдэл үүсэх аюул, тосон ГТ дэлбэрэх аюул арилна. Хоёрдугаарт инженерчлэлийн уян хатан байдал: шинэ хамгаалалт, тоолуур нэмэхэд шинэ ГТ цөм, кабель шаардлагагүй, зөвхөн SV урсгалд бүртгүүлнэ.", "h": "Шинэ хэмжүүрийн технологи ба процессын шинын нэгдэл нь дэд станцын хоёрдогч системд чанарын өөрчлөлт авчирна (Хүснэгт 5.8). Хамгийн чухал нь <b>аюулгүй байдал</b>: ГТ-ийн хоёрдогч хэлхээг задлахад мянга мянган вольтын хүчдэл үүсэх аюул, тосон ГТ дэлбэрэх аюул арилна. Хоёрдугаарт <b>инженерчлэлийн уян хатан байдал</b>: шинэ хамгаалалт, тоолуур нэмэхэд шинэ ГТ цөм, кабель шаардлагагүй, зөвхөн SV урсгалд бүртгүүлнэ."}, {"t": "cap", "s": "Хүснэгт 5.8. Уламжлалт ба дижитал хэмжилтийн системийн харьцуулалт", "h": "Хүснэгт 5.8. Уламжлалт ба дижитал хэмжилтийн системийн харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Үзүүлэлт", "Уламжлалт (ГТ/ХТ + зэс кабель)", "Дижитал (LPIT/SAMU + процессын шина)"], "rows": [["Хоёрдогч кабель", "Олон зуун км (том дэд станцад)", "50–80 % бага, оптик"], ["ГТ-ийн хоёрдогч задрах аюул", "Бий", "Байхгүй (LPIT) / зөвхөн SAMU хүртэл"], ["Ханалт, феррорезонанс", "Бий", "Байхгүй (LPIT)"], ["Хэмжилтийг дахин ашиглах", "Цөм тус бүр тусдаа", "Нэг урсгалыг олон IED"], ["Хоцрогдол", "≈ 0", "1–2 мс"], ["Цагийн эх үүсвэрээс хамаарал", "Үгүй", "Тийм (PTP, holdover)"], ["Кибер аюулгүй байдал", "Физик хандалт", "Сүлжээний сегментчлэл, IEC 62351"], ["Туршилт, засвар", "Гүйдэл тарих, кабель тасдах", "Програмын симуляц, SV тест горим"], ["Мэргэжилтний ур чадвар", "Уламжлалт релейчин", "Сүлжээ, IEC 61850, програм хангамж"]]}, {"t": "p", "s": "Сорилтууд: (1) хоцрогдол ба цагийн синхрончлолоос хамаарах шинэ эрсдэл; (2) өөр үйлдвэрлэгчийн MU ба IED-ийн харилцан нийцэл (interoperability) — IEC 61850 Edition 2, IEC 61869-9 профайлын зөрүү; (3) кибер аюулгүй байдал; (4) засвар үйлчилгээний ажилтны шинэ ур чадвар, туршилтын тоног төхөөрөмж (SV генератор, сүлжээний анализатор) ба LPIT-ийн урт хугацааны ажиллагааны туршлага хязгаарлагдмал.", "h": "Сорилтууд: (1) хоцрогдол ба цагийн синхрончлолоос хамаарах шинэ эрсдэл; (2) өөр үйлдвэрлэгчийн MU ба IED-ийн харилцан нийцэл (interoperability) — IEC 61850 Edition 2, IEC 61869-9 профайлын зөрүү; (3) кибер аюулгүй байдал; (4) засвар үйлчилгээний ажилтны шинэ ур чадвар, туршилтын тоног төхөөрөмж (SV генератор, сүлжээний анализатор) ба LPIT-ийн урт хугацааны ажиллагааны туршлага хязгаарлагдмал."}, {"t": "h", "l": 2, "s": "6.2. Монголын нөхцөл ба\nнэвтрүүлэх зам", "h": "6.2. Монголын нөхцөл ба\nнэвтрүүлэх зам"}, {"t": "p", "s": "Монголын 110–220 кВ-ын дэд станцуудад тосон ГТ (ТФЗМ, ТГФ төрөл), индуктив ХТ (НКФ), 220 кВ-д CVT зонхилж, 6–35 кВ-д НТМИ, НАМИ, ЗНОЛ төрлийн ХТ, ТПЛ, ТОЛ төрлийн ГТ ашиглагдаж байна. Шинэчлэлийн стратегид дараах зарчмыг баримтлахыг санал болгоно:", "h": "Монголын 110–220 кВ-ын дэд станцуудад тосон ГТ (ТФЗМ, ТГФ төрөл), индуктив ХТ (НКФ), 220 кВ-д CVT зонхилж, 6–35 кВ-д НТМИ, НАМИ, ЗНОЛ төрлийн ХТ, ТПЛ, ТОЛ төрлийн ГТ ашиглагдаж байна. Шинэчлэлийн стратегид дараах зарчмыг баримтлахыг санал болгоно:"}, {"t": "p", "s": "Хүйтэн уур амьсгал. −40 °C-д SF6-тэй ГТ-ийн даралт буурч, тос зуурамтгай болдог. Тос, хийгүй оптик ГТ, Роговскийн ороомог илүү найдвартай; ил талбайн SAMU-г −40 °C-ийн туршилттай сонгоно.", "h": "1. <b>Хүйтэн уур амьсгал.</b> −40 °C-д SF6-тэй ГТ-ийн даралт буурч, тос зуурамтгай болдог. Тос, хийгүй оптик ГТ, Роговскийн ороомог илүү найдвартай; ил талбайн SAMU-г −40 °C-ийн туршилттай сонгоно."}, {"t": "p", "s": "Феррорезонанс. 6–35 кВ-ын тусгаарлагдсан нейтральтай сүлжээнд ХТ шатах асуудлыг антирезонансын ХТ эсвэл резистив LPVT-ээр шийдэх нь хамгийн үр дүнтэй.", "h": "2. <b>Феррорезонанс.</b> 6–35 кВ-ын тусгаарлагдсан нейтральтай сүлжээнд ХТ шатах асуудлыг антирезонансын ХТ эсвэл резистив LPVT-ээр шийдэх нь хамгийн үр дүнтэй."}, {"t": "p", "s": "Арилжааны тоолуур. Эрчим хүчний зах зээл, сэргээгдэх эх үүсвэрийн тооцоонд 0.2S ангийн ГТ, 0.2 ангийн ХТ-ийг шинэ холболтын цэгүүдэд заавал хэрэглэх; хоёрдогч ачааллыг бодитоор хэмжиж баталгаажуулах.", "h": "3. <b>Арилжааны тоолуур.</b> Эрчим хүчний зах зээл, сэргээгдэх эх үүсвэрийн тооцоонд 0.2S ангийн ГТ, 0.2 ангийн ХТ-ийг шинэ холболтын цэгүүдэд заавал хэрэглэх; хоёрдогч ачааллыг бодитоор хэмжиж баталгаажуулах."}, {"t": "p", "s": "Үе шаттай шилжилт. SAMU-д суурилсан туршилтын бэйг уламжлалт хамгаалалттай зэрэгцээ (shadow mode) ажиллуулж, дараа нь КРУЭ/GIS-ийн LPIT нэвтрүүлэх.", "h": "4. <b>Үе шаттай шилжилт.</b> SAMU-д суурилсан туршилтын бэйг уламжлалт хамгаалалттай зэрэгцээ (shadow mode) ажиллуулж, дараа нь КРУЭ/GIS-ийн LPIT нэвтрүүлэх."}, {"t": "p", "s": "Норм ба мэргэжилтэн. IEC 61869-ийг үндэсний стандарт болгох, IEC 61850/61869-ийн лабораторийн стенд байгуулах.", "h": "5. <b>Норм ба мэргэжилтэн.</b> IEC 61869-ийг үндэсний стандарт болгох, IEC 61850/61869-ийн лабораторийн стенд байгуулах."}, {"t": "h", "l": 1, "s": "Нэр томьёо", "h": "Нэр томьёо"}, {"t": "tbl", "s": "", "head": ["Монгол", "Англи", "Орос"], "rows": [["Гүйдлийн трансформатор (ГТ)", "Current transformer (CT)", "Трансформатор тока (ТТ)"], ["Хүчдэлийн трансформатор (ХТ)", "Voltage transformer (VT)", "Трансформатор напряжения (ТН)"], ["Багтаамжийн ХТ", "Capacitor voltage transformer (CVT)", "Емкостный трансформатор напряжения"], ["Нарийвчлалын анги", "Accuracy class", "Класс точности"], ["Хязгаарын хүчин зүйл", "Accuracy limit factor (ALF)", "Номинальная предельная кратность"], ["Хугарлын цэг", "Knee point", "Точка перегиба (колена)"], ["Үлдэгдэл соронзлол", "Remanence", "Остаточная намагниченность"], ["Феррорезонанс", "Ferroresonance", "Феррорезонанс"], ["Оптик ГТ", "Optical current transformer", "Оптический трансформатор тока"], ["Верде тогтмол", "Verdet constant", "Постоянная Верде"], ["Роговскийн ороомог", "Rogowski coil", "Пояс (катушка) Роговского"], ["Бага чадлын хэмжүүрийн трансформатор", "Low-power instrument transformer (LPIT)", "Маломощный измерительный трансформатор"], ["Хүчдэл хуваагч", "Voltage divider", "Делитель напряжения"], ["Нэгтгэх төхөөрөмж", "Merging unit (MU)", "Устройство сопряжения с шиной процесса (ПАС)"], ["Түүвэрлэлтийн утга", "Sampled values (SV)", "Мгновенные значения (выборки)"], ["Процессын шина", "Process bus", "Шина процесса"]]}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "Дүгнэлт"}, {"t": "p", "s": "Уламжлалт ГТ-ийн хамгаалалтын чадварыг хугарлын цэгийн хүчдэл, бодит ачаалал, X/R харьцаа, үлдэгдэл соронзлол тодорхойлно: тогтмол бүрэлдэхүүнтэй гүйдлийг ханалтгүй хувиргахад E k тэгш хэмт горимынхоос (1+X/R)/(1−K r) дахин их байх шаардлагатай.", "h": "• Уламжлалт ГТ-ийн хамгаалалтын чадварыг хугарлын цэгийн хүчдэл, бодит ачаалал, X/R харьцаа, үлдэгдэл соронзлол тодорхойлно: тогтмол бүрэлдэхүүнтэй гүйдлийг ханалтгүй хувиргахад E<sub>k</sub> тэгш хэмт горимынхоос (1+X/R)/(1−K<sub>r</sub>) дахин их байх шаардлагатай."}, {"t": "p", "s": "Хамгаалалтын ГТ-ийн ангийг (5P, PX, TPY, TPZ) хамгаалалтын төрөл, ажиллах хугацаагаар сонгож, (5.10), (5.11)-ээр шалгана.", "h": "• Хамгаалалтын ГТ-ийн ангийг (5P, PX, TPY, TPZ) хамгаалалтын төрөл, ажиллах хугацаагаар сонгож, (5.10), (5.11)-ээр шалгана."}, {"t": "p", "s": "Индуктив ХТ-ийн феррорезонанс нь Монголын 6–35 кВ-ын тусгаарлагдсан нейтральтай сүлжээний түгээмэл асуудал бөгөөд сааруулах резистор, антирезонансын ХТ, LPVT-ээр шийдэгдэнэ; CVT нь 110 кВ-оос дээш хүчдэлд хэмнэлттэй боловч шилжилтийн ба давтамжийн хязгаарлалттай.", "h": "• Индуктив ХТ-ийн феррорезонанс нь Монголын 6–35 кВ-ын тусгаарлагдсан нейтральтай сүлжээний түгээмэл асуудал бөгөөд сааруулах резистор, антирезонансын ХТ, LPVT-ээр шийдэгдэнэ; CVT нь 110 кВ-оос дээш хүчдэлд хэмнэлттэй боловч шилжилтийн ба давтамжийн хязгаарлалттай."}, {"t": "p", "s": "Оптик ГТ (Фарадейн эффект) ба Роговскийн ороомог нь ханалтгүй, шугаман, өргөн зурвастай, аюулгүй мэдрэгч бөгөөд нэг мэдрэгч хэмжүүрийн ба хамгаалалтын үүргийг хамт гүйцэтгэнэ; температурын нөхөн олговор, интеграторын тогтвортой байдал гол анхаарах зүйл.", "h": "• Оптик ГТ (Фарадейн эффект) ба Роговскийн ороомог нь ханалтгүй, шугаман, өргөн зурвастай, аюулгүй мэдрэгч бөгөөд нэг мэдрэгч хэмжүүрийн ба хамгаалалтын үүргийг хамт гүйцэтгэнэ; температурын нөхөн олговор, интеграторын тогтвортой байдал гол анхаарах зүйл."}, {"t": "p", "s": "IEC 61869-9-өөр MU нь 4800 Гц (хамгаалалт, хэмжилт) эсвэл 14 400 Гц (эрчим хүчний чанар)-ээр синхрон түүвэрлэж, SV урсгалыг процессын шинаар дамжуулна; нэг урсгал ≈ 4.7 Мбит/с, хоцрогдол 1–2 мс.", "h": "• IEC 61869-9-өөр MU нь 4800 Гц (хамгаалалт, хэмжилт) эсвэл 14 400 Гц (эрчим хүчний чанар)-ээр синхрон түүвэрлэж, SV урсгалыг процессын шинаар дамжуулна; нэг урсгал ≈ 4.7 Мбит/с, хоцрогдол 1–2 мс."}, {"t": "p", "s": "Дижитал хэмжилтийн нарийвчлалыг мэдрэгч, MU, синхрончлолын алдааны нийлбэрээр үнэлнэ; 1 мкс-ийн цагийн алдаа 50 Гц-д 1.08′ фазын алдаа өгдөг тул PTP синхрончлол зайлшгүй.", "h": "• Дижитал хэмжилтийн нарийвчлалыг мэдрэгч, MU, синхрончлолын алдааны нийлбэрээр үнэлнэ; 1 мкс-ийн цагийн алдаа 50 Гц-д 1.08′ фазын алдаа өгдөг тул PTP синхрончлол зайлшгүй."}, {"t": "p", "s": "Монголд шинэчлэлийг хүйтэн уур амьсгал, феррорезонансыг харгалзан SAMU-д суурилсан туршилтын бэйгээс эхлүүлэх нь зохистой.", "h": "• Монголд шинэчлэлийг хүйтэн уур амьсгал, феррорезонансыг харгалзан SAMU-д суурилсан туршилтын бэйгээс эхлүүлэх нь зохистой."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "Хяналтын асуулт"}, {"t": "p", "s": "ГТ-ийн гүйдлийн алдаа, фазын шилжилт, хуримтлагдсан алдааг тодорхойлж, ялгааг тайлбарла.", "h": "1. ГТ-ийн гүйдлийн алдаа, фазын шилжилт, хуримтлагдсан алдааг тодорхойлж, ялгааг тайлбарла."}, {"t": "p", "s": "Бодит ачаалал нэрлэснээс бага бол хязгаарын хүчин зүйл яагаад өсдөг вэ? (5.4)-өөр тайлбарла.", "h": "2. Бодит ачаалал нэрлэснээс бага бол хязгаарын хүчин зүйл яагаад өсдөг вэ? (5.4)-өөр тайлбарла."}, {"t": "p", "s": "Тогтмол бүрэлдэхүүн ГТ-ийг яагаад ханалтад оруулдаг вэ? (5.8) томьёонд X/R ба K r-ийн үүргийг тайлбарла.", "h": "3. Тогтмол бүрэлдэхүүн ГТ-ийг яагаад ханалтад оруулдаг вэ? (5.8) томьёонд X/R ба K<sub>r</sub>-ийн үүргийг тайлбарла."}, {"t": "p", "s": "TPX, TPY, TPZ ангийн ГТ-ийн бүтэц, хэрэглээний ялгааг харьцуул.", "h": "4. TPX, TPY, TPZ ангийн ГТ-ийн бүтэц, хэрэглээний ялгааг харьцуул."}, {"t": "p", "s": "Феррорезонанс үүсэх нөхцөл, Зураг 5.4-ийн гурван горимыг тайлбарлаж, 6–10 кВ-ын сүлжээнд хэрэглэх хамгаалах арга хэмжээг нэрлэ.", "h": "5. Феррорезонанс үүсэх нөхцөл, Зураг 5.4-ийн гурван горимыг тайлбарлаж, 6–10 кВ-ын сүлжээнд хэрэглэх хамгаалах арга хэмжээг нэрлэ."}, {"t": "p", "s": "CVT-ийн тааруулах реакторын үүрэг юу вэ? CVT-ийг гармоник хэмжихэд яагаад хэрэглэдэггүй вэ?", "h": "6. CVT-ийн тааруулах реакторын үүрэг юу вэ? CVT-ийг гармоник хэмжихэд яагаад хэрэглэдэггүй вэ?"}, {"t": "p", "s": "Фарадейн эффектэд суурилсан оптик ГТ-ийн ажиллах зарчим, (5.17)-д 4-ийн коэффициент хаанаас үүсдэгийг тайлбарла.", "h": "7. Фарадейн эффектэд суурилсан оптик ГТ-ийн ажиллах зарчим, (5.17)-д 4-ийн коэффициент хаанаас үүсдэгийг тайлбарла."}, {"t": "p", "s": "Роговскийн ороомгийн гаралт яагаад гүйдлийн уламжлалд пропорциональ вэ? Интеграторын үүрэг, сул талыг тайлбарла.", "h": "8. Роговскийн ороомгийн гаралт яагаад гүйдлийн уламжлалд пропорциональ вэ? Интеграторын үүрэг, сул талыг тайлбарла."}, {"t": "p", "s": "IEC 61869-9-ийн 4800 ба 14 400 Гц-ийн түүвэрлэлт ямар хэрэглээнд зориулагдсан бэ? Нэг үеийн түүврийн тоо, хэмжих хамгийн их гармоникийг тооцоол.", "h": "9. IEC 61869-9-ийн 4800 ба 14 400 Гц-ийн түүвэрлэлт ямар хэрэглээнд зориулагдсан бэ? Нэг үеийн түүврийн тоо, хэмжих хамгийн их гармоникийг тооцоол."}, {"t": "p", "s": "SAMU ба LPIT-д суурилсан MU-ийн ялгаа юу вэ? Одоо ашиглагдаж буй дэд станцыг процессын шинад шилжүүлэхэд аль нь тохиромжтой вэ?", "h": "10. SAMU ба LPIT-д суурилсан MU-ийн ялгаа юу вэ? Одоо ашиглагдаж буй дэд станцыг процессын шинад шилжүүлэхэд аль нь тохиромжтой вэ?"}, {"t": "h", "l": 1, "s": "Ном зүй", "h": "Ном зүй"}, {"t": "p", "s": "IEC 61869-2:2012. Instrument transformers — Part 2: Additional requirements for current transformers.", "h": "1. IEC 61869-2:2012. Instrument transformers — Part 2: Additional requirements for current transformers."}, {"t": "p", "s": "IEC 61869-3:2011; IEC 61869-5:2011. Instrument transformers — Additional requirements for inductive and capacitor voltage transformers.", "h": "2. IEC 61869-3:2011; IEC 61869-5:2011. Instrument transformers — Additional requirements for inductive and capacitor voltage transformers."}, {"t": "p", "s": "IEC 61869-9:2016. Instrument transformers — Part 9: Digital interface for instrument transformers.", "h": "3. IEC 61869-9:2016. Instrument transformers — Part 9: Digital interface for instrument transformers."}, {"t": "p", "s": "IEC 61869-10:2017; IEC 61869-11:2017. Instrument transformers — Additional requirements for low-power passive current and voltage transformers.", "h": "4. IEC 61869-10:2017; IEC 61869-11:2017. Instrument transformers — Additional requirements for low-power passive current and voltage transformers."}, {"t": "p", "s": "IEEE Std C37.110-2007. IEEE Guide for the Application of Current Transformers Used for Protective Relaying Purposes.", "h": "5. IEEE Std C37.110-2007. IEEE Guide for the Application of Current Transformers Used for Protective Relaying Purposes."}, {"t": "p", "s": "IEC 61850-9-2:2011. Communication networks and systems for power utility automation — Part 9-2: Specific communication service mapping (SCSM) — Sampled values over ISO/IEC 8802-3.", "h": "6. IEC 61850-9-2:2011. Communication networks and systems for power utility automation — Part 9-2: Specific communication service mapping (SCSM) — Sampled values over ISO/IEC 8802-3."}];